import js from '@eslint/js'
import globals from 'globals'
import reactHooks from 'eslint-plugin-react-hooks'
import reactRefresh from 'eslint-plugin-react-refresh'
import tseslint from 'typescript-eslint'

export default tseslint.config(
  { ignores: ['dist'] },
  {
    extends: [js.configs.recommended, ...tseslint.configs.recommended],
    files: ['**/*.{ts,tsx}'],
    languageOptions: {
      ecmaVersion: 2020,
      globals: globals.browser,
    },
    plugins: {
      'react-hooks': reactHooks,
      'react-refresh': reactRefresh,
    },
    rules: {
      ...reactHooks.configs.recommended.rules,
      'react-refresh/only-export-components': [
        'warn',
        { allowConstantExport: true },
      ],
    },
  },
)

export default {
  plugins: {
    tailwindcss: {},
    autoprefixer: {},
  },
}

import React, { memo, useEffect, useCallback } from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { useDispatch } from 'react-redux';
import ToastProvider from './components/ui/ToastProvider';
import InvalidTokenProvider from './components/common/InvalidTokenProvider';
import { ThemeProvider } from './contexts/ThemeContext';
import ErrorBoundary from './components/common/ErrorBoundary';
import RouteWrapper from './components/common/RouteWrapper';
import SEOHead from './components/common/SEOHead';
import LayoutWrapper from './components/layout/LayoutWrapper';
import { useWebVitals, usePerformanceMonitor, useAppRoutes } from './hooks';
import { fetchTenant } from './store/slices/tenantSlice';
import { fetchStores } from './store/slices/storeSlice';
import { AppDispatch } from './store/store';

const App = memo(() => {
  const dispatch = useDispatch<AppDispatch>();
  const { markRenderStart, markRenderEnd } = usePerformanceMonitor('App');

  // Initialize app
  const init = useCallback(() => {
    dispatch(fetchTenant());
    dispatch(fetchStores());
    // Preload critical pages
    setTimeout(() => {
      import('./pages/ProductListPage');
      import('./pages/CartPage');
    }, 2000);
  }, [dispatch]);

  useEffect(() => {
    markRenderStart();
    init();
    const timer = setTimeout(markRenderEnd, 100);
    return () => clearTimeout(timer);
  }, [init, markRenderStart, markRenderEnd]);

  useWebVitals();
  const routes = useAppRoutes();

  return (
    <ErrorBoundary>
      <ThemeProvider>
        <Router>
          <SEOHead />
          <ToastProvider />
          <InvalidTokenProvider>
            <Routes>
              {routes.map(({ path, element, fallback, layout = true }) => (
                <Route
                  key={path}
                  path={path}
                  element={
                    <LayoutWrapper showHeader={layout} showFooter={layout}>
                      <RouteWrapper fallback={fallback}>
                        {element}
                      </RouteWrapper>
                    </LayoutWrapper>
                  }
                />
              ))}
            </Routes>
          </InvalidTokenProvider>
        </Router>
      </ThemeProvider>
    </ErrorBoundary>
  );
});

App.displayName = 'App';

export default App;

import React, { Component, ErrorInfo, ReactNode } from 'react';
import { AlertTriangle, RefreshCw, Home } from 'lucide-react';

interface Props {
  children: ReactNode;
}

interface State {
  hasError: boolean;
  error: Error | null;
  isRecovering: boolean;
}

class ErrorBoundary extends Component<Props, State> {
  private recoveryTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(props: Props) {
    super(props);
    this.state = { hasError: false, error: null, isRecovering: false };
  }

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { hasError: true, error };
  }

  componentDidCatch(error: Error, errorInfo: ErrorInfo) {
    console.error('Error Boundary caught an error:', error, errorInfo);
    this.setState({ error });
    this.attemptRecovery();
  }

  private attemptRecovery = () => {
    this.setState({ isRecovering: true });
    this.recoveryTimer = setTimeout(() => {
      this.setState({ hasError: false, error: null, isRecovering: false });
    }, 3000);
  };

  private reset = () => {
    this.setState({ hasError: false, error: null, isRecovering: false });
  };

  componentWillUnmount() {
    if (this.recoveryTimer) clearTimeout(this.recoveryTimer);
  }

  render() {
    if (!this.state.hasError) return this.props.children;

    const containerClass = "min-h-screen bg-gradient-to-br from-purple-50 via-pink-50 to-sky-50 flex items-center justify-center p-4";
    const cardClass = "bg-white rounded-2xl shadow-xl p-8 max-w-md w-full";

    if (this.state.isRecovering) {
      return (
        <div className={containerClass}>
          <div className={`${cardClass} text-center`}>
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-purple-600 mx-auto mb-4"></div>
            <h2 className="text-xl font-semibold text-gray-900 mb-2">⚠️ Recovering from an error… Please wait.</h2>
            <p className="text-gray-600">We're automatically fixing the issue. This should only take a moment.</p>
          </div>
        </div>
      );
    }

    return (
      <div className={containerClass}>
        <div className={cardClass}>
          <div className="text-center">
            <div className="mx-auto flex items-center justify-center h-16 w-16 rounded-full bg-red-100 mb-6">
              <AlertTriangle className="h-8 w-8 text-red-600" />
            </div>
            <h2 className="text-2xl font-bold text-gray-900 mb-4">Something went wrong</h2>
            <p className="text-gray-600 mb-6">We encountered an unexpected error. Please try again.</p>

            <div className="space-y-3">
              <button onClick={this.reset} className="w-full bg-purple-600 hover:bg-purple-700 text-white font-medium py-3 px-6 rounded-xl transition-all duration-200 flex items-center justify-center">
                <RefreshCw className="h-5 w-5 mr-2" />Try Again
              </button>
              <button onClick={() => window.location.href = '/'} className="w-full bg-gray-100 hover:bg-gray-200 text-gray-700 font-medium py-3 px-6 rounded-xl transition-all duration-200 flex items-center justify-center">
                <Home className="h-5 w-5 mr-2" />Go Home
              </button>
            </div>

            {process.env.NODE_ENV === 'development' && this.state.error && (
              <details className="mt-6 text-left">
                <summary className="cursor-pointer text-sm text-gray-500 hover:text-gray-700">Error Details (Development Only)</summary>
                <div className="mt-2 p-4 bg-gray-50 rounded-lg text-xs font-mono text-gray-700 overflow-auto max-h-40">
                  <div className="mb-2"><strong>Error:</strong> {this.state.error.message}</div>
                  <div className="mb-2"><strong>Stack:</strong><pre className="whitespace-pre-wrap">{this.state.error.stack}</pre></div>
                </div>
              </details>
            )}
          </div>
        </div>
      </div>
    );
  }
}

export default ErrorBoundary;

import React, { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';

interface InvalidTokenModalProps {
  isOpen: boolean;
  onClose: () => void;
  message?: string;
}

const InvalidTokenModal: React.FC<InvalidTokenModalProps> = ({ 
  isOpen, 
  onClose,
  message = "Your session has expired. Please login again to continue."
}) => {
  const navigate = useNavigate();

  useEffect(() => {
    // Prevent body scroll when modal is open
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'unset';
    }

    return () => {
      document.body.style.overflow = 'unset';
    };
  }, [isOpen]);

  const handleRedirectToLogin = () => {
    onClose();
    navigate('/login', { replace: true });
  };

  const handleBackdropClick = (e: React.MouseEvent<HTMLDivElement>) => {
    if (e.target === e.currentTarget) {
      handleRedirectToLogin();
    }
  };

  if (!isOpen) return null;

  return (
    <div 
      className="fixed inset-0 z-[9999] flex items-center justify-center bg-black/50 backdrop-blur-sm animate-fadeIn"
      onClick={handleBackdropClick}
      role="dialog"
      aria-modal="true"
      aria-labelledby="invalid-token-title"
      aria-describedby="invalid-token-description"
    >
      <div className="relative w-full max-w-md mx-4 bg-white dark:bg-gray-800 rounded-2xl shadow-2xl transform transition-all animate-scaleIn">
        {/* Icon */}
        <div className="flex justify-center pt-8 pb-4">
          <div className="w-16 h-16 bg-red-100 dark:bg-red-900/30 rounded-full flex items-center justify-center">
            <svg 
              className="w-8 h-8 text-red-600 dark:text-red-400" 
              fill="none" 
              stroke="currentColor" 
              viewBox="0 0 24 24"
              aria-hidden="true"
            >
              <path 
                strokeLinecap="round" 
                strokeLinejoin="round" 
                strokeWidth={2} 
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" 
              />
            </svg>
          </div>
        </div>

        {/* Content */}
        <div className="px-8 pb-6 text-center">
          <h3 
            id="invalid-token-title"
            className="text-2xl font-bold text-gray-900 dark:text-white mb-3"
          >
            Session Expired
          </h3>
          <p 
            id="invalid-token-description"
            className="text-gray-600 dark:text-gray-300 mb-6 leading-relaxed"
          >
            {message}
          </p>

          {/* Action Button */}
          <button
            onClick={handleRedirectToLogin}
            className="w-full px-6 py-3 bg-gradient-to-r from-blue-600 to-blue-700 hover:from-blue-700 hover:to-blue-800 text-white font-semibold rounded-lg shadow-lg hover:shadow-xl transform hover:scale-[1.02] active:scale-[0.98] transition-all duration-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:ring-offset-2 dark:focus:ring-offset-gray-800"
            autoFocus
          >
            Go to Login
          </button>
        </div>

        {/* Decorative elements */}
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-red-500 via-orange-500 to-yellow-500 rounded-t-2xl"></div>
      </div>
    </div>
  );
};

export default InvalidTokenModal;

import React, { useEffect } from 'react';
import { useInvalidTokenModal } from '../../hooks';
import InvalidTokenModal from './InvalidTokenModal';
import { invalidTokenEvent } from '../../services/apiClient';

const InvalidTokenProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const { isOpen, openModal, closeModal, message, setMessage } = useInvalidTokenModal();

  useEffect(() => {
    const handleInvalidToken = (event: Event) => {
      const customEvent = event as CustomEvent<{ message: string }>;
      const errorMessage = customEvent.detail?.message || 'Your session has expired. Please login again to continue.';
      setMessage(errorMessage);
      openModal();
    };

    // Listen for invalid token events
    invalidTokenEvent.addEventListener('invalidToken', handleInvalidToken);

    return () => {
      invalidTokenEvent.removeEventListener('invalidToken', handleInvalidToken);
    };
  }, [openModal, setMessage]);

  return (
    <>
      {children}
      <InvalidTokenModal 
        isOpen={isOpen} 
        onClose={closeModal}
        message={message}
      />
    </>
  );
};

export default InvalidTokenProvider;

