import { useState, useCallback, useEffect, useMemo } from 'react';
import { useAppSelector } from '../redux';
import { useToast } from '../ui/useToast';
import { validateUserName, validateEmail, validatePhoneNumber } from '../../utils';

interface ProfileFormData {
  user_name: string;
  email_address: string;
  phone_number: string;
}

const VALIDATORS = {
  user_name: validateUserName,
  email_address: validateEmail,
  phone_number: validatePhoneNumber,
} as const;

const MAX_IMAGE_SIZE = 5 * 1024 * 1024; // 5MB

interface UseAccountProfileReturn {
  profileData: ProfileFormData;
  errors: Partial<Record<keyof ProfileFormData, string>>;
  loading: boolean;
  hasChanges: boolean;
  isEditing: boolean;
  profileImage: string | null;
  isUploading: boolean;
  updateField: (field: keyof ProfileFormData, value: string) => void;
  saveProfile: () => Promise<boolean>;
  resetForm: () => void;
  startEditing: () => void;
  cancelEditing: () => void;
  handleImageUpload: (file: File) => Promise<void>;
}

export const useAccountProfile = (): UseAccountProfileReturn => {
  const { user, loading: authLoading } = useAppSelector((state) => state.auth);
  const { success, error } = useToast();
  
  const [profileData, setProfileData] = useState<ProfileFormData>({
    user_name: '',
    email_address: '',
    phone_number: '',
  });
  
  const [originalData, setOriginalData] = useState<ProfileFormData>(profileData);
  const [errors, setErrors] = useState<Partial<Record<keyof ProfileFormData, string>>>({});
  const [loading, setLoading] = useState(false);
  const [isEditing, setIsEditing] = useState(false);
  const [profileImage, setProfileImage] = useState<string | null>(null);
  const [isUploading, setIsUploading] = useState(false);

  useEffect(() => {
    if (user) {
      const data = {
        user_name: user.user_name || '',
        email_address: user.email_address || '',
        phone_number: user.phone_number || '',
      };
      setProfileData(data);
      setOriginalData(data);
    }
  }, [user]);

  const hasChanges = useMemo(() => 
    JSON.stringify(profileData) !== JSON.stringify(originalData),
    [profileData, originalData]
  );

  const updateField = useCallback((field: keyof ProfileFormData, value: string) => {
    setProfileData(prev => ({ ...prev, [field]: value }));
    setErrors(prev => ({ ...prev, [field]: undefined }));
  }, []);

  const validateForm = useCallback((): boolean => {
    const newErrors: Partial<Record<keyof ProfileFormData, string>> = {};
    (Object.keys(VALIDATORS) as (keyof ProfileFormData)[]).forEach(field => {
      const err = VALIDATORS[field](profileData[field]);
      if (err) newErrors[field] = err;
    });
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [profileData]);

  const resetForm = useCallback(() => {
    setProfileData(originalData);
    setErrors({});
    setIsEditing(false);
  }, [originalData]);

  const saveProfile = useCallback(async (): Promise<boolean> => {
    if (!validateForm()) {
      error('Please fix the errors before saving');
      return false;
    }

    setLoading(true);
    try {
      // TODO: API call - await userApi.updateProfile(profileData);
      await new Promise(resolve => setTimeout(resolve, 1000));
      
      setOriginalData(profileData);
      setIsEditing(false);
      success('Profile updated successfully');
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update profile';
      error(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  }, [profileData, validateForm, success, error]);

  const handleImageUpload = useCallback(async (file: File): Promise<void> => {
    if (!file.type.startsWith('image/')) {
      error('Please select an image file');
      return;
    }

    if (file.size > MAX_IMAGE_SIZE) {
      error('Image size should be less than 5MB');
      return;
    }

    setIsUploading(true);
    try {
      const imageUrl = URL.createObjectURL(file);
      setProfileImage(imageUrl);
      // TODO: Upload to server - await userApi.uploadProfileImage(file);
      success('Profile image updated');
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to upload image';
      error(errorMessage);
    } finally {
      setIsUploading(false);
    }
  }, [success, error]);

  return {
    profileData,
    errors,
    loading: loading || authLoading,
    hasChanges,
    isEditing,
    profileImage,
    isUploading,
    updateField,
    saveProfile,
    resetForm,
    startEditing: () => setIsEditing(true),
    cancelEditing: resetForm,
    handleImageUpload,
  };
};

import { useState, useCallback, useEffect } from 'react';
import { useAppSelector } from '../redux';
import { useToast } from '../ui/useToast';
import { useLocalStorage } from '../utils/useLocalStorage';

interface AccountSettingsData {
  notifications: {
    emailNotifications: boolean;
    orderUpdates: boolean;
    promotionalEmails: boolean;
  };
  privacy: {
    profileVisibility: 'public' | 'private';
    allowDataCollection: boolean;
  };
  security: {
    twoFactorEnabled: boolean;
    loginAlerts: boolean;
  };
  preferences: {
    language: string;
    theme: 'light' | 'dark' | 'system';
    itemsPerPage: number;
  };
}

const DEFAULT_SETTINGS: AccountSettingsData = {
  notifications: { emailNotifications: true, orderUpdates: true, promotionalEmails: false },
  privacy: { profileVisibility: 'private', allowDataCollection: true },
  security: { twoFactorEnabled: false, loginAlerts: true },
  preferences: { language: 'en', theme: 'system', itemsPerPage: 12 },
};

interface UseAccountSettingsReturn {
  settings: AccountSettingsData;
  loading: boolean;
  hasChanges: boolean;
  updateSetting: <T extends keyof AccountSettingsData>(
    category: T,
    key: keyof AccountSettingsData[T],
    value: AccountSettingsData[T][keyof AccountSettingsData[T]]
  ) => void;
  saveSettings: () => Promise<boolean>;
  resetSettings: () => void;
  toggleTwoFactor: () => Promise<boolean>;
  changePassword: (currentPassword: string, newPassword: string) => Promise<boolean>;
}

export const useAccountSettings = (): UseAccountSettingsReturn => {
  const { user } = useAppSelector((state) => state.auth);
  const { success, error } = useToast();
  
  const [localPreferences, setLocalPreferences] = useLocalStorage(
    'userPreferences', 
    DEFAULT_SETTINGS.preferences
  );
  
  const [settings, setSettings] = useState<AccountSettingsData>(DEFAULT_SETTINGS);
  const [originalSettings, setOriginalSettings] = useState<AccountSettingsData>(DEFAULT_SETTINGS);
  const [loading, setLoading] = useState(false);

  const loadSettings = useCallback(async () => {
    if (!user) return;
    setLoading(true);
    try {
      // TODO: API call - await userApi.getSettings();
      await new Promise(resolve => setTimeout(resolve, 300));
      const loaded = { ...DEFAULT_SETTINGS, preferences: localPreferences };
      setSettings(loaded);
      setOriginalSettings(loaded);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to load settings';
      error(errorMessage);
    } finally {
      setLoading(false);
    }
  }, [user, localPreferences, error]);

  const updateSetting = useCallback(<T extends keyof AccountSettingsData>(
    category: T, 
    key: keyof AccountSettingsData[T], 
    value: AccountSettingsData[T][keyof AccountSettingsData[T]]
  ) => {
    setSettings(prev => ({
      ...prev,
      [category]: { ...prev[category], [key]: value }
    }));
    
    if (category === 'preferences') {
      setLocalPreferences({ ...settings.preferences, [key]: value });
    }
  }, [settings.preferences, setLocalPreferences]);

  const saveSettings = useCallback(async (): Promise<boolean> => {
    setLoading(true);
    try {
      // TODO: API call - await userApi.updateSettings(settings);
      await new Promise(resolve => setTimeout(resolve, 500));
      setOriginalSettings(settings);
      success('Settings saved successfully');
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to save settings';
      error(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  }, [settings, success, error]);

  const toggleTwoFactor = useCallback(async (): Promise<boolean> => {
    setLoading(true);
    try {
      // TODO: API call - await authApi.toggleTwoFactor(!settings.security.twoFactorEnabled);
      await new Promise(resolve => setTimeout(resolve, 500));
      const newValue = !settings.security.twoFactorEnabled;
      updateSetting('security', 'twoFactorEnabled', newValue);
      success(newValue ? '2FA enabled' : '2FA disabled');
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update 2FA';
      error(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  }, [settings.security.twoFactorEnabled, updateSetting, success, error]);

  const changePassword = useCallback(async (currentPassword: string, newPassword: string): Promise<boolean> => {
    setLoading(true);
    try {
      // TODO: API call - await authApi.changePassword({ currentPassword, newPassword });
      await new Promise(resolve => setTimeout(resolve, 500));
      success('Password changed successfully');
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to change password';
      error(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  }, [success, error]);

  useEffect(() => {
    if (user) loadSettings();
  }, [user]);

  return {
    settings,
    loading,
    hasChanges: JSON.stringify(settings) !== JSON.stringify(originalSettings),
    updateSetting,
    saveSettings,
    resetSettings: () => {
      setSettings(originalSettings);
      setLocalPreferences(originalSettings.preferences);
    },
    toggleTwoFactor,
    changePassword,
  };
};

import { useState, useCallback, useEffect, useMemo } from 'react';
import { useAppSelector, useAppDispatch } from '../redux';
import { useToast } from '../ui/useToast';
import { Address } from '../../types/api';
import { 
  fetchUserAddresses, 
  createAddress, 
  updateAddress, 
  deleteAddress as deleteAddressAction, 
  setDefaultAddress as setDefaultAddressAction 
} from '../../store/slices/addressSlice';

interface AddressFormData {
  address_tag: string;
  complete_address: string;
  city: string;
  state: string;
  country: string;
  pincode: string;
  landmark?: string;
  is_default: boolean;
}

const INITIAL_FORM: AddressFormData = {
  address_tag: 'Home',
  complete_address: '',
  city: '',
  state: '',
  country: 'India',
  pincode: '',
  landmark: '',
  is_default: false,
};

const VALIDATORS: Record<string, (v: any) => string> = {
  address_tag: (v: string) => !v?.trim() ? 'Label is required' : v.trim().length < 2 ? 'Label too short' : '',
  complete_address: (v: string) => !v?.trim() ? 'Address is required' : v.trim().length < 10 ? 'Address too short' : '',
  city: (v: string) => !v?.trim() ? 'City is required' : '',
  state: (v: string) => !v?.trim() ? 'State is required' : '',
  country: (v: string) => !v?.trim() ? 'Country is required' : '',
  pincode: (v: string) => !v?.trim() ? 'PIN code is required' : !/^\d{5,6}$/.test(v.trim()) ? 'Invalid PIN code' : '',
};

interface UseAddressBookReturn {
  addresses: Address[];
  selectedAddress: Address | null;
  defaultAddress: Address | null;
  formData: AddressFormData;
  errors: Partial<Record<keyof AddressFormData, string>>;
  isEditing: boolean;
  loading: boolean;
  showForm: boolean;
  editingAddress: Address | null;
  fetchAddresses: () => Promise<void>;
  selectAddress: (address: Address | null) => void;
  startEditing: (address?: Address) => void;
  cancelEditing: () => void;
  updateField: (field: keyof AddressFormData, value: string | boolean) => void;
  saveAddress: () => Promise<boolean>;
  deleteAddress: (addressId: string) => Promise<boolean>;
  setAsDefault: (addressId: string) => Promise<boolean>;
  openForm: (address?: Address) => void;
  closeForm: () => void;
  handleEdit: (address?: Address) => void;
  handleDelete: (addressId: string) => Promise<void>;
  handleSetDefault: (addressId: string) => Promise<void>;
  handleSubmit: (e: React.FormEvent) => Promise<void>;
  hasAddresses: boolean;
}

export const useAddressBook = (): UseAddressBookReturn => {
  const dispatch = useAppDispatch();
  const { user } = useAppSelector((state) => state.auth);
  const { addresses, loading } = useAppSelector((state) => state.address);
  const { success, error } = useToast();
  
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);
  const [formData, setFormData] = useState<AddressFormData>(INITIAL_FORM);
  const [errors, setErrors] = useState<Partial<Record<keyof AddressFormData, string>>>({});
  const [editingId, setEditingId] = useState<string | null>(null);
  const [showForm, setShowForm] = useState(false);

  const defaultAddress = useMemo(() => 
    addresses.find(addr => addr.is_default) || null, 
    [addresses]
  );

  const fetchAddresses = useCallback(async () => {
    if (!user) return;
    try {
      await dispatch(fetchUserAddresses()).unwrap();
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      error(errorMessage || 'Failed to fetch addresses');
    }
  }, [user, dispatch, error]);

  const updateField = useCallback((field: keyof AddressFormData, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    setErrors(prev => ({ ...prev, [field]: undefined }));
  }, []);

  const validateForm = useCallback((): boolean => {
    const newErrors: Partial<Record<keyof AddressFormData, string>> = {};
    Object.keys(VALIDATORS).forEach(field => {
      const value = formData[field as keyof AddressFormData];
      if (value !== undefined) {
        const err = VALIDATORS[field]?.(value);
        if (err) newErrors[field as keyof AddressFormData] = err;
      }
    });
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  }, [formData]);

  const openForm = useCallback((address?: Address) => {
    if (address) {
      setFormData({
        address_tag: address.address_tag,
        complete_address: address.complete_address || address.address || '',
        city: address.city,
        state: address.state,
        country: address.country,
        pincode: address.pincode,
        landmark: address.landmark || '',
        is_default: address.is_default,
      });
      setEditingId(address.b2c_address_uid);
    } else {
      setFormData(INITIAL_FORM);
      setEditingId(null);
    }
    setShowForm(true);
    setErrors({});
  }, []);

  const closeForm = useCallback(() => {
    setShowForm(false);
    setEditingId(null);
    setFormData(INITIAL_FORM);
    setErrors({});
  }, []);

  const handleSubmit = useCallback(async (e: React.FormEvent) => {
    e.preventDefault();
    
    if (!validateForm()) {
      error('Please fix the errors before saving');
      return;
    }

    try {
      if (editingId) {
        await dispatch(updateAddress({ addressId: editingId, addressData: formData })).unwrap();
        success('Address updated');
      } else {
        await dispatch(createAddress(formData)).unwrap();
        success('Address added');
      }
      closeForm();
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      error(errorMessage || 'Failed to save address');
    }
  }, [formData, editingId, validateForm, dispatch, success, error, closeForm]);

  const handleDelete = useCallback(async (addressId: string) => {
    const addr = addresses.find(a => a.b2c_address_uid === addressId);
    if (addresses.length <= 1) {
      error('Must have at least one address');
      return;
    }
    if (addr?.is_default) {
      error('Cannot delete default address');
      return;
    }

    if (window.confirm('Are you sure you want to delete this address?')) {
      try {
        await dispatch(deleteAddressAction(addressId)).unwrap();
        success('Address deleted');
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        error(errorMessage || 'Failed to delete address');
      }
    }
  }, [addresses, dispatch, success, error]);

  const handleSetDefault = useCallback(async (addressId: string) => {
    try {
      await dispatch(setDefaultAddressAction(addressId)).unwrap();
      success('Default address updated');
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      error(errorMessage || 'Failed to update default address');
    }
  }, [dispatch, success, error]);

  useEffect(() => {
    if (user) fetchAddresses();
  }, [user]);

  return {
    addresses,
    selectedAddress,
    defaultAddress,
    formData,
    errors,
    isEditing: !!editingId,
    loading,
    showForm,
    editingAddress: editingId ? addresses.find(a => a.b2c_address_uid === editingId) || null : null,
    fetchAddresses,
    selectAddress: setSelectedAddress,
    startEditing: openForm,
    cancelEditing: closeForm,
    updateField,
    saveAddress: async () => {
      if (!validateForm()) {
        error('Please fix the errors before saving');
        return false;
      }
      try {
        if (editingId) {
          await dispatch(updateAddress({ addressId: editingId, addressData: formData })).unwrap();
          success('Address updated');
        } else {
          await dispatch(createAddress(formData)).unwrap();
          success('Address added');
        }
        closeForm();
        return true;
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        error(errorMessage || 'Failed to save address');
        return false;
      }
    },
    deleteAddress: async (addressId: string) => {
      const addr = addresses.find(a => a.b2c_address_uid === addressId);
      if (addresses.length <= 1 || addr?.is_default) {
        error(addresses.length <= 1 ? 'Must have at least one address' : 'Cannot delete default address');
        return false;
      }
      try {
        await dispatch(deleteAddressAction(addressId)).unwrap();
        success('Address deleted');
        return true;
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        error(errorMessage || 'Failed to delete address');
        return false;
      }
    },
    setAsDefault: async (addressId: string) => {
      try {
        await dispatch(setDefaultAddressAction(addressId)).unwrap();
        success('Default address updated');
        return true;
      } catch (err) {
        const errorMessage = err instanceof Error ? err.message : String(err);
        error(errorMessage || 'Failed to update default address');
        return false;
      }
    },
    openForm,
    closeForm,
    handleEdit: openForm,
    handleDelete,
    handleSetDefault,
    handleSubmit,
    hasAddresses: addresses.length > 0,
  };
};

import { useEffect, useMemo, useCallback } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { fetchUserOrders } from '../../store/slices/orderSlice';
import { fetchUserAddresses } from '../../store/slices/addressSlice';
import { getUserWishlist } from '../../store/slices/wishlistSlice';
import { DEFAULT_LIMIT, DEFAULTS, INITIAL_OFFSET } from '../../utils';
import { OrderListItem } from '../../types/api';

const COMPLETED_STATUSES = ['delivered', 'cancelled'];

interface DashboardStats {
  totalOrders: number;
  totalSpent: number;
  savedAddresses: number;
  wishlistItems: number;
}

interface UseDashboardReturn {
  stats: DashboardStats;
  recentOrders: OrderListItem[];
  pendingOrdersCount: number;
  loading: boolean;
  hasDefaultAddress: boolean;
  fetchDashboardData: () => void;
}

export const useDashboard = (): UseDashboardReturn => {
  const dispatch = useAppDispatch();
  const { orders, totalOrderCount, main } = useAppSelector((state) => state.order);
  const { addresses } = useAppSelector((state) => state.address);
  const { wishlistItems } = useAppSelector((state) => state.wishlist);
  const defaultStore = useAppSelector((state) => state.store.defaultStore);

  const fetchDashboardData = useCallback(() => {
    if (defaultStore?.store_uid) {
      dispatch(fetchUserOrders({ limit: DEFAULT_LIMIT, page: INITIAL_OFFSET, store_uid: defaultStore.store_uid }));
      dispatch(fetchUserAddresses());
      dispatch(getUserWishlist());
    }
  }, [dispatch, defaultStore?.store_uid]);

  useEffect(() => {
    fetchDashboardData();
  }, [fetchDashboardData]);

  const stats = useMemo(() => {
    const totalSpent = orders
      .filter(o => {
        const status = o.milestone_code?.toLowerCase();
        return status !== 'can' && status !== 'chk';
      })
      .reduce((sum, o) => sum + (o.total_price || 0), 0);
    
    return {
      totalOrders: totalOrderCount || orders.length,
      totalSpent,
      savedAddresses: addresses.length,
      wishlistItems: wishlistItems.length,
    };
  }, [orders, totalOrderCount, addresses.length, wishlistItems.length]);

  const recentOrders = useMemo(() => 
    orders.slice(0, 5), [orders]);
    
  const pendingOrdersCount = useMemo(() => 
    orders.filter(o => !COMPLETED_STATUSES.includes(o.milestone_code.toLowerCase())).length,
    [orders]
  );

  return {
    stats,
    recentOrders,
    pendingOrdersCount,
    loading: main.loading,
    hasDefaultAddress: addresses.some(addr => addr.is_default),
    fetchDashboardData,
  };
};

import { useState, useCallback, useEffect, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { useToast } from '../ui/useToast';
import { 
  fetchUserOrders,
  fetchOrderDetails as fetchOrderDetailsThunk,
  fetchOrderTimeline,
  fetchOrderUserDetails,
  fetchOrderSummary
} from '../../store/slices/orderSlice';
import { OrderListItem, OrderProduct, OrderSummary, OrderTimeline, OrderUserDetails } from '../../types/api';

interface OrderFilters {
  status: string;
  dateRange: { start: Date | null; end: Date | null };
  searchTerm: string;
  sortBy: 'date_desc' | 'date_asc' | 'amount_desc' | 'amount_asc';
}

const INITIAL_FILTERS: OrderFilters = {
  status: 'all',
  dateRange: { start: null, end: null },
  searchTerm: '',
  sortBy: 'date_desc',
};

const ITEMS_PER_PAGE = 10;

const SORT_FNS = {
  date_asc: (a: OrderListItem, b: OrderListItem) => 
    new Date(a.creation_date).getTime() - new Date(b.creation_date).getTime(),
  date_desc: (a: OrderListItem, b: OrderListItem) => 
    new Date(b.creation_date).getTime() - new Date(a.creation_date).getTime(),
  amount_asc: (a: OrderListItem, b: OrderListItem) => a.total_price - b.total_price,
  amount_desc: (a: OrderListItem, b: OrderListItem) => b.total_price - a.total_price,
};

interface OrderStatistics {
  totalOrders: number;
  totalSpent: number;
  averageOrderValue: number;
}

interface OrderDetailsState {
  products: OrderProduct[];
  summary: OrderSummary | null;
  timeline: OrderTimeline[];
  userDetails: OrderUserDetails | null;
  loading: boolean;
  error: string | null;
}

interface UseOrderHistoryReturn {
  orders: OrderListItem[];
  filteredOrders: OrderListItem[];
  selectedOrder: OrderListItem | null;
  orderDetails: OrderDetailsState;
  loading: boolean;
  error: string | null;
  filters: OrderFilters;
  currentPage: number;
  totalPages: number;
  showFilters: boolean;
  sortBy: 'date' | 'amount' | 'status';
  sortOrder: 'asc' | 'desc';
  fetchOrders: (page?: number) => Promise<void>;
  fetchOrderDetails: (orderUid: string) => Promise<void>;
  updateFilters: (newFilters: Partial<OrderFilters>) => void;
  clearFilters: () => void;
  selectOrder: (order: OrderListItem | null) => void;
  changePage: (page: number) => void;
  toggleFilters: () => void;
  handleSortChange: (field: 'date' | 'amount' | 'status') => void;
  toggleSortOrder: () => void;
  handleViewDetails: (order: OrderListItem) => void;
  handleReorder: (order: OrderListItem) => void;
  hasOrders: boolean;
  orderStatistics: OrderStatistics;
}

export const useOrderHistory = (): UseOrderHistoryReturn => {
  const dispatch = useAppDispatch();
  const { user } = useAppSelector((state) => state.auth);
  const orderState = useAppSelector((state) => state.order);
  const { error: errorToast } = useToast();

  const [selectedOrder, setSelectedOrder] = useState<OrderListItem | null>(null);
  const [filters, setFilters] = useState<OrderFilters>(INITIAL_FILTERS);
  const [currentPage, setCurrentPage] = useState(1);
  const [showFilters, setShowFilters] = useState(false);

  const totalPages = Math.ceil(orderState.totalOrderCount / ITEMS_PER_PAGE);

  const fetchOrders = useCallback(async (page = 1) => {
    if (!user) return;
    try {
      await dispatch(fetchUserOrders({
        limit: ITEMS_PER_PAGE,
        page,
        store_uid: user.store?.store_uid,
      })).unwrap();
      setCurrentPage(page);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      errorToast(errorMessage || 'Failed to fetch orders');
    }
  }, [dispatch, user, errorToast]);

  const fetchOrderDetails = useCallback(async (orderUid: string) => {
    try {
      await Promise.all([
        dispatch(fetchOrderDetailsThunk(orderUid)).unwrap(),
        dispatch(fetchOrderTimeline(orderUid)).unwrap(),
        dispatch(fetchOrderUserDetails(orderUid)).unwrap(),
        dispatch(fetchOrderSummary(orderUid)).unwrap(),
      ]);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : String(err);
      errorToast(errorMessage || 'Failed to fetch order details');
    }
  }, [dispatch, errorToast]);

  const filteredOrders = useMemo(() => {
    let result = orderState.orders;

    if (filters.status !== 'all') {
      result = result.filter(o => o.milestone_code.toLowerCase() === filters.status.toLowerCase());
    }

    if (filters.dateRange.start || filters.dateRange.end) {
      result = result.filter(o => {
        const date = new Date(o.creation_date);
        return (!filters.dateRange.start || date >= filters.dateRange.start) &&
               (!filters.dateRange.end || date <= filters.dateRange.end);
      });
    }

    if (filters.searchTerm) {
      const term = filters.searchTerm.toLowerCase();
      result = result.filter(o =>
        o.order_serial_number.toLowerCase().includes(term) ||
        o.product_name.toLowerCase().includes(term)
      );
    }

    return [...result].sort(SORT_FNS[filters.sortBy]);
  }, [orderState.orders, filters]);

  const orderStatistics = useMemo(() => {
    const totalOrders = orderState.totalOrderCount || orderState.orders.length;
    const totalSpent = orderState.orders.reduce((sum, o) => sum + o.total_price, 0);
    return {
      totalOrders,
      totalSpent,
      averageOrderValue: totalOrders > 0 ? totalSpent / totalOrders : 0,
    };
  }, [orderState.orders, orderState.totalOrderCount]);

  const updateFilters = useCallback((newFilters: Partial<OrderFilters>) => {
    setFilters(prev => ({ ...prev, ...newFilters }));
  }, []);

  const selectOrder = useCallback((order: OrderListItem | null) => {
    setSelectedOrder(order);
    if (order) fetchOrderDetails(order.order_uid);
  }, [fetchOrderDetails]);

  const changePage = useCallback((page: number) => {
    if (page >= 1 && page <= totalPages) fetchOrders(page);
  }, [fetchOrders, totalPages]);

  useEffect(() => {
    if (user) fetchOrders();
  }, [user]);

  return {
    orders: orderState.orders,
    filteredOrders,
    selectedOrder,
    orderDetails: {
      products: orderState.orderDetails,
      summary: orderState.orderSummary,
      timeline: orderState.timeline,
      userDetails: orderState.userDetails,
      loading: orderState.main.loading,
      error: orderState.main.error,
    },
    loading: orderState.main.loading,
    error: orderState.main.error,
    filters,
    currentPage,
    totalPages,
    showFilters,
    sortBy: filters.sortBy.split('_')[0] as 'date' | 'amount' | 'status',
    sortOrder: filters.sortBy.split('_')[1] as 'asc' | 'desc',
    fetchOrders,
    fetchOrderDetails,
    updateFilters,
    clearFilters: () => setFilters(INITIAL_FILTERS),
    selectOrder,
    changePage,
    toggleFilters: () => setShowFilters(prev => !prev),
    handleSortChange: (field: 'date' | 'amount' | 'status') => {
      const order = filters.sortBy.split('_')[1] as 'asc' | 'desc';
      setFilters(prev => ({ ...prev, sortBy: `${field}_${order}` as OrderFilters['sortBy'] }));
    },
    toggleSortOrder: () => {
      const field = filters.sortBy.split('_')[0] as 'date' | 'amount';
      const newOrder = filters.sortBy.split('_')[1] === 'asc' ? 'desc' : 'asc';
      setFilters(prev => ({ ...prev, sortBy: `${field}_${newOrder}` as OrderFilters['sortBy'] }));
    },
    handleViewDetails: (order: OrderListItem) => window.location.href = `/orders/${order.order_uid}`,
    handleReorder: (order: OrderListItem) => console.log('Reordering:', order.order_uid),
    hasOrders: orderState.orders.length > 0,
    orderStatistics,
  };
};

