import { useState, useCallback, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { loginUser } from '../../store/slices/authSlice';
import { useToast } from '../ui/useToast';

interface LoginCredentials {
  email_address: string;
  password: string;
  rememberMe?: boolean;
}

interface UseLoginReturn {
  credentials: LoginCredentials;
  errors: Record<string, string>;
  loading: boolean;
  handleInputChange: (field: keyof LoginCredentials, value: string | boolean) => void;
  handleSubmit: (e: React.FormEvent) => Promise<boolean>;
  validateField: (field: keyof LoginCredentials) => void;
  clearErrors: () => void;
}

const initialCredentials: LoginCredentials = {
  email_address: '',
  password: '',
  rememberMe: false,
};

export const useLogin = (): UseLoginReturn => {
  const dispatch = useAppDispatch();
  const { loading } = useAppSelector((state) => state.auth);
  const { success, error: errorToast } = useToast();
  
  const [credentials, setCredentials] = useState<LoginCredentials>(initialCredentials);
  const [errors, setErrors] = useState<Record<string, string>>({});

  const handleInputChange = useCallback((field: keyof LoginCredentials, value: string | boolean) => {
    setCredentials(prev => ({ ...prev, [field]: value }));
    
    // Clear error for this field when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  }, [errors]);

  // Memoize email regex to avoid recreation
  const emailRegex = useMemo(() => /^[^\s@]+@[^\s@]+\.[^\s@]+$/, []);

  const validateField = useCallback((field: keyof LoginCredentials) => {
    const value = credentials[field];
    
    if (field === 'email_address') {
      if (!value || typeof value !== 'string') {
        setErrors(prev => ({ ...prev, [field]: 'Email is required' }));
      } else if (!emailRegex.test(value)) {
        setErrors(prev => ({ ...prev, [field]: 'Please enter a valid email address' }));
      } else {
        setErrors(prev => ({ ...prev, [field]: '' }));
      }
    } else if (field === 'password') {
      if (!value || typeof value !== 'string') {
        setErrors(prev => ({ ...prev, [field]: 'Password is required' }));
      } else if (value.length < 6) {
        setErrors(prev => ({ ...prev, [field]: 'Password must be at least 6 characters' }));
      } else {
        setErrors(prev => ({ ...prev, [field]: '' }));
      }
    }
  }, [credentials, emailRegex]);

  const clearErrors = useCallback(() => {
    setErrors({});
  }, []);

  const handleSubmit = useCallback(async (e: React.FormEvent): Promise<boolean> => {
    e.preventDefault();
    
    // Validate form
    validateField('email_address');
    validateField('password');
    
    // Check for errors after validation
    const currentErrors = errors;
    if (currentErrors.email_address || currentErrors.password) {
      errorToast('Please fix the errors below');
      return false;
    }

    try {
      const result = await dispatch(loginUser({
        email_address: credentials.email_address,
        password: credentials.password,
      }));
      if (loginUser.fulfilled.match(result)) {
        success(`Welcome back, ${result.payload.user.user_name}!`);
        // Reset form
        setCredentials(initialCredentials);
        setErrors({});
        return true; // Login successful
      } else if (loginUser.rejected.match(result)) {
        const errorMessage = result.payload as string || 'Login failed';
        
        // Check if the error is about OTP login requirement
        if (errorMessage.includes('OTP login') || errorMessage.includes('password login')) {
          errorToast('Please use OTP login for this account. Click "Login with OTP" below.');
        } else {
          errorToast(errorMessage);
        }
        return false; // Login failed
      }
      return false; // Default to failed
    } catch (err) {
      errorToast('An unexpected error occurred. Please try again.');
      return false; // Login failed
    }
  }, [dispatch, credentials, errors, errorToast, success, validateField]);

  return {
    credentials,
    errors,
    loading,
    handleInputChange,
    handleSubmit,
    validateField,
    clearErrors,
  };
};

import { useState, useCallback, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { sendOtp, verifyOtp } from '../../store/slices/authSlice';
import { useToast } from '../ui/useToast';

interface OTPData {
  phone_number: string;
  otp: string;
}

interface UseOTPReturn {
  otpData: OTPData;
  errors: Record<string, string>;
  loading: boolean;
  otpSent: boolean;
  handleInputChange: (field: keyof OTPData, value: string) => void;
  handleSendOTP: () => Promise<void>;
  handleVerifyOTP: (e: React.FormEvent) => Promise<boolean>;
  validateField: (field: keyof OTPData) => void;
  clearErrors: () => void;
  resetOTP: () => void;
}

const initialOTPData: OTPData = {
  phone_number: '',
  otp: '',
};

export const useOTP = (): UseOTPReturn => {
  const dispatch = useAppDispatch();
  const { loading } = useAppSelector((state) => state.auth);
  const { success, error: errorToast } = useToast();
  
  const [otpData, setOtpData] = useState<OTPData>(initialOTPData);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const [otpSent, setOtpSent] = useState(false);

  const handleInputChange = useCallback((field: keyof OTPData, value: string) => {
    setOtpData(prev => ({ ...prev, [field]: value }));
    
    // Clear error for this field when user starts typing
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  }, [errors]);

  // Memoize regex patterns to avoid recreation
  const phoneRegex = useMemo(() => /^[\+]?[1-9][\d]{0,15}$/, []);
  const otpRegex = useMemo(() => /^\d{6}$/, []);

  const validateField = useCallback((field: keyof OTPData) => {
    const value = otpData[field];
    
    if (field === 'phone_number') {
      if (!value) {
        setErrors(prev => ({ ...prev, [field]: 'Phone number is required' }));
      } else if (!phoneRegex.test(value.replace(/\s/g, ''))) {
        setErrors(prev => ({ ...prev, [field]: 'Please enter a valid phone number' }));
      } else {
        setErrors(prev => ({ ...prev, [field]: '' }));
      }
    } else if (field === 'otp') {
      if (!value) {
        setErrors(prev => ({ ...prev, [field]: 'OTP is required' }));
      } else if (value.length !== 6) {
        setErrors(prev => ({ ...prev, [field]: 'OTP must be 6 digits' }));
      } else if (!otpRegex.test(value)) {
        setErrors(prev => ({ ...prev, [field]: 'OTP must contain only numbers' }));
      } else {
        setErrors(prev => ({ ...prev, [field]: '' }));
      }
    }
  }, [otpData, phoneRegex, otpRegex]);

  const clearErrors = useCallback(() => {
    setErrors({});
  }, []);

  const handleSendOTP = useCallback(async () => {
    // Validate phone number first
    validateField('phone_number');
    
    // Check for errors after validation
    const currentErrors = errors;
    if (currentErrors.phone_number) {
      errorToast('Please fix the phone number error');
      return;
    }

    try {
      const result = await dispatch(sendOtp(otpData.phone_number));

      if (sendOtp.fulfilled.match(result)) {
        success('OTP sent successfully! Check your phone for the verification code.');
        setOtpSent(true);
      } else if (sendOtp.rejected.match(result)) {
        const errorMessage = result.payload as string || 'Failed to send OTP';
        errorToast(errorMessage);
      }
    } catch (err) {
      errorToast('An unexpected error occurred. Please try again.');
    }
  }, [dispatch, otpData.phone_number, errors, errorToast, success, validateField]);

  const handleVerifyOTP = useCallback(async (e: React.FormEvent): Promise<boolean> => {
    e.preventDefault();
    
    validateField('otp');
    
    // Check for errors after validation
    const currentErrors = errors;
    if (currentErrors.otp) {
      errorToast('Please fix the OTP error');
      return false;
    }

    try {
      const result = await dispatch(verifyOtp({
        otp: otpData.otp,
        phone_number: otpData.phone_number,
      }));

      if (verifyOtp.fulfilled.match(result)) {
        success(`Welcome back, ${result.payload.user.user_name}!`);
        // Reset form
        setOtpData(initialOTPData);
        setErrors({});
        setOtpSent(false);
        return true; // OTP verification successful
      } else if (verifyOtp.rejected.match(result)) {
        const errorMessage = result.payload as string || 'OTP verification failed';
        errorToast(errorMessage);
        return false; // OTP verification failed
      }
      return false; // Default to failed
    } catch (err) {
      errorToast('An unexpected error occurred. Please try again.');
      return false; // OTP verification failed
    }
  }, [dispatch, otpData, errors, errorToast, success, validateField]);

  const resetOTP = useCallback(() => {
    setOtpData(initialOTPData);
    setErrors({});
    setOtpSent(false);
  }, []);

  return {
    otpData,
    errors,
    loading,
    otpSent,
    handleInputChange,
    handleSendOTP,
    handleVerifyOTP,
    validateField,
    clearErrors,
    resetOTP,
  };
};

import { useState, useMemo, useCallback } from 'react';
import { getPasswordStrength, getPasswordStrengthLabel } from '../../utils/formValidation';

interface PasswordRequirement {
  id: string;
  label: string;
  met: boolean;
}

interface UsePasswordStrengthReturn {
  strength: number;
  strengthLabel: string;
  requirements: PasswordRequirement[];
  isStrong: boolean;
  checkRequirement: (requirement: string) => boolean;
}

export const usePasswordStrength = (password: string): UsePasswordStrengthReturn => {
  const strength = useMemo(() => getPasswordStrength(password), [password]);
  const strengthLabel = useMemo(() => getPasswordStrengthLabel(strength), [strength]);
  const isStrong = useMemo(() => strength >= 4, [strength]);

  const requirements: PasswordRequirement[] = useMemo(() => [
    { id: 'length', label: 'At least 8 characters', met: password.length >= 8 },
    { id: 'uppercase', label: 'One uppercase letter', met: /[A-Z]/.test(password) },
    { id: 'lowercase', label: 'One lowercase letter', met: /[a-z]/.test(password) },
    { id: 'number', label: 'One number', met: /\d/.test(password) },
    { id: 'special', label: 'One special character', met: /[!@#$%^&*()_+\-=\[\]{};':"\\|,.<>\/?]/.test(password) },
  ], [password]);

  const checkRequirement = useCallback((requirement: string): boolean => {
    const req = requirements.find(r => r.id === requirement);
    return req?.met || false;
  }, [requirements]);

  return {
    strength,
    strengthLabel,
    requirements,
    isStrong,
    checkRequirement,
  };
};

import { useState, useCallback, useRef } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { registerUser, loginUser } from '../../store/slices/authSlice';
import { useToast } from '../ui/useToast';
import { FormData, validateRegistrationForm } from '../../utils/formValidation';

interface UseRegistrationReturn {
  formData: FormData;
  errors: Record<string, string>;
  loading: boolean;
  handleInputChange: (field: keyof FormData, value: string | boolean) => void;
  handleSubmit: (e: React.FormEvent) => Promise<boolean>;
  validateField: (field: keyof FormData) => void;
  clearErrors: () => void;
}

const initialFormData: FormData = {
  user_name: '',
  phone_number: '',
  email_address: '',
  password: '',
  confirm_password: '',
  termsAccepted: false,
};

export const useRegistration = (): UseRegistrationReturn => {
  const dispatch = useAppDispatch();
  const { loading } = useAppSelector((state) => state.auth);
  const { success, error: errorToast } = useToast();
  
  const [formData, setFormData] = useState<FormData>(initialFormData);
  const [errors, setErrors] = useState<Record<string, string>>({});
  
  // Use ref to avoid recreating handleInputChange on every error change
  const errorsRef = useRef(errors);
  errorsRef.current = errors;

  const handleInputChange = useCallback((field: keyof FormData, value: string | boolean) => {
    setFormData(prev => ({ ...prev, [field]: value }));
    
    // Clear error for this field when user starts typing
    if (errorsRef.current[field]) {
      setErrors(prev => {
        const { [field]: _, ...rest } = prev;
        return rest;
      });
    }
  }, []);

  const validateField = useCallback((field: keyof FormData) => {
    // Validate on-demand, only when explicitly called
    const { errors: validationErrors } = validateRegistrationForm(formData);
    if (validationErrors[field]) {
      setErrors(prev => ({ ...prev, [field]: validationErrors[field]! }));
    }
  }, [formData]);

  const clearErrors = useCallback(() => {
    setErrors({});
  }, []);

  // Helper to handle auto-login after registration
  const handleAutoLogin = useCallback(async (credentials: { email_address: string; password: string }) => {
    try {
      const loginResult = await dispatch(loginUser(credentials));
      
      if (loginUser.fulfilled.match(loginResult)) {
        success(`Welcome, ${loginResult.payload.user.user_name}!`);
        setFormData(initialFormData);
        setErrors({});
        return true;
      } else {
        errorToast('Registration successful! Please log in manually.');
        setFormData(initialFormData);
        setErrors({});
        return true;
      }
    } catch (loginErr) {
      console.error('Auto-login error:', loginErr);
      errorToast('Registration successful! Please log in manually.');
      setFormData(initialFormData);
      setErrors({});
      return true;
    }
  }, [dispatch, success, errorToast]);

  const handleSubmit = useCallback(async (e: React.FormEvent): Promise<boolean> => {
    e.preventDefault();
    
    // Validate only on submit
    const { isValid, errors: validationErrors } = validateRegistrationForm(formData);
    
    if (!isValid) {
      setErrors(validationErrors as Record<string, string>);
      errorToast('Please fix the errors below');
      return false;
    }

    try {
      const credentials = {
        email_address: formData.email_address,
        password: formData.password,
      };

      const result = await dispatch(registerUser({
        user_name: formData.user_name,
        email_address: formData.email_address,
        password: formData.password,
        phone_number: formData.phone_number,
      }));

      console.log('Registration result:', result);
      
      // Check if registration was successful
      const isSuccess = registerUser.fulfilled.match(result);
      
      if (isSuccess) {
        success('Registration successful! Logging you in...');
        return await handleAutoLogin(credentials);
      } else if (registerUser.rejected.match(result)) {
        const errorMessage = result.payload as string || 'Registration failed';
        errorToast(errorMessage);
        return false;
      } else {
        errorToast('Registration failed. Please try again.');
        return false;
      }
    } catch (err) {
      console.error('Registration error:', err);
      errorToast('An unexpected error occurred. Please try again.');
      return false;
    }
  }, [dispatch, formData, errorToast, success, handleAutoLogin]);

  return {
    formData,
    errors,
    loading,
    handleInputChange,
    handleSubmit,
    validateField,
    clearErrors,
  };
};

import { useModal } from '../utils/useModal';

