export { useCart } from './useCart';
export { useCartActions } from './useCartActions';
export { useCartItem } from './useCartItem';
export { useCheckout } from './useCheckout';
export { useCoupon } from './useCoupon';
export { useCouponInput } from './useCouponInput';
export { usePricing } from './usePricing';
export { usePricingSummary } from './usePricingSummary';

import { useEffect, useState, useCallback, useMemo } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../redux';
import { 
  fetchBag, 
  incrementQuantity, 
  decrementQuantity, 
  removeFromCart, 
  syncGuestCart 
} from '../../store/slices/cartSlice';
import { addToWishlist } from '../../store/slices/wishlistSlice';
import { useToast } from '../ui/useToast';
import { useCoupon } from './useCoupon';
import { usePricing } from './usePricing';
import { useDerivedCartItems } from '../../utils/cartDataHelpers';
import { UserCoupon, CartItem, BagDetail, DeliveryCharge } from '../../types/api';
import { CouponDiscountResult, CouponFilterOptions, CouponSortBy } from '../../utils/couponUtils';

interface PricingInfo {
  subtotal: number;
  deliveryCharge: number;
  baseDeliveryCharge: number;
  deliveryDiscount: number;
  productDiscount: number;
  discount: number;
  tax: number;
  codCharge: number;
  total: number;
  couponApplied: boolean;
  isFreeDelivery: boolean;
}

interface PricingSummaryInfo {
  subtotal: string;
  deliveryCharge: string;
  baseDeliveryCharge: string;
  deliveryDiscount: string;
  productDiscount: string;
  discount: string;
  tax: string;
  codCharge: string;
  total: string;
  savings: string;
}

interface DeliveryChargeInfo {
  baseCharge: number;
  finalCharge: number;
  saved: number;
  isFree: boolean;
  hasDiscount: boolean;
}

interface CouponStats {
  total: number;
  valid: number;
  invalid: number;
  bestSavings: number;
  appliedSavings: number;
}

interface BestCouponInfo {
  coupon: UserCoupon | null;
  savings: number;
  discount: CouponDiscountResult | null;
}

interface InvalidCouponInfo {
  coupon: UserCoupon;
  validation: {
    isValid: boolean;
    message?: string;
    reason?: string;
  };
}

interface UseCartReturn {
  // Cart state
  cartItems: (CartItem | BagDetail)[];
  isGuest: boolean;
  loading: boolean;
  error: string | null;
  totalItems: number;
  isUpdating: boolean;
  hasInitialized: boolean;
  
  // Pricing
  pricing: PricingInfo;
  pricingSummary: PricingSummaryInfo;
  totalSavings: number;
  potentialSavings: number;
  discountBreakdown: Array<{ label: string; amount: number }>;
  deliveryChargeInfo: DeliveryChargeInfo;
  deliveryCharge: DeliveryCharge | null;
  deliveryChargeLoading: boolean;
  isFreeDeliveryEligible: boolean;
  
  // Coupons
  appliedCoupon: UserCoupon | null;
  appliedDiscount: CouponDiscountResult | null;
  availableCoupons: UserCoupon[];
  validCoupons: UserCoupon[];
  invalidCoupons: InvalidCouponInfo[];
  bestCoupon: BestCouponInfo;
  couponsLoading: boolean;
  couponStats: CouponStats;
  
  // Cart actions
  handleIncrement: (uid: string, id?: number) => void;
  handleDecrement: (uid: string, id?: number) => void;
  handleRemove: (uid: string, id?: number) => void;
  handleMoveToWishlist: (uid: string) => Promise<void>;
  handleCheckout: () => void;
  
  // Coupon actions
  handleApplyCoupon: (code: string) => Promise<boolean>;
  handleApplyCouponDirect: (coupon: UserCoupon) => Promise<boolean>;
  handleRemoveCoupon: () => void;
  applyBestCoupon: () => void;
  previewDiscount: (coupon: UserCoupon) => CouponDiscountResult | null;
  refreshCoupons: () => void;
  updateFilters: (options: Partial<CouponFilterOptions>) => void;
  clearFilters: () => void;
  setSortBy: (sortBy: CouponSortBy) => void;
  
  // Utilities
  filterOptions: CouponFilterOptions;
  sortBy: CouponSortBy;
  formatCurrency: (amount: number) => string;
  refreshDeliveryCharge: () => void;
}

export const useCart = (): UseCartReturn => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { success, error: showError } = useToast();

  const { 
    bags, guestItems, loading, error, totalAmount,
    isAuthenticated, user, defaultStore, baseDeliveryCharge 
  } = useAppSelector((state) => ({
    bags: state.cart.bags,
    guestItems: state.cart.guestItems,
    loading: state.cart.loading,
    error: state.cart.error,
    totalAmount: state.cart.totalAmount,
    isAuthenticated: state.auth.isAuthenticated,
    user: state.auth.user,
    defaultStore: state.store.defaultStore,
    baseDeliveryCharge: state.deliveryCharge.deliveryCharge?.delivery_charge || 0,
  }));

  const [isUpdating, setIsUpdating] = useState(false);
  const [hasInitialized, setHasInitialized] = useState(false);

  const isGuest = !isAuthenticated;
  const cartItems = useDerivedCartItems(isGuest, guestItems, bags);
  const totalItems = cartItems.reduce((sum, item) => sum + item.product_count, 0);
  const couponConfig = useMemo(() => ({
    isAuthenticated,
    userUid: user?.user_uid,
    cartTotal: totalAmount,
    deliveryCharge: baseDeliveryCharge,
    cartItems,
    isOnlinePayment: false,
  }), [isAuthenticated, user?.user_uid, totalAmount, baseDeliveryCharge, cartItems]);

  const {
    appliedCoupon,
    appliedDiscount,
    availableCoupons,
    validCoupons,
    invalidCoupons,
    bestCoupon,
    couponsLoading,
    couponStats,
    handleApplyCoupon,
    handleApplyCouponDirect,
    handleRemoveCoupon,
    applyBestCoupon,
    previewDiscount,
    refreshCoupons,
    updateFilters,
    clearFilters,
    setSortBy,
    filterOptions,
    sortBy,
  } = useCoupon(couponConfig);

  // Pricing hook with memoized config
  const pricingConfig = useMemo(() => ({
    subtotal: totalAmount,
    appliedCoupon,
    appliedDiscount,
    storeUid: defaultStore?.store_uid,
  }), [totalAmount, appliedCoupon, appliedDiscount, defaultStore?.store_uid]);

  const {
    pricing,
    pricingSummary,
    totalSavings,
    potentialSavings,
    discountBreakdown,
    deliveryChargeInfo,
    deliveryCharge,
    deliveryChargeLoading,
    isFreeDeliveryEligible,
    formatCurrency,
    refreshDeliveryCharge,
  } = usePricing(pricingConfig);

  useEffect(() => {
    if (defaultStore?.store_uid) {
      dispatch(fetchBag(defaultStore.store_uid)).finally(() => {
        setHasInitialized(true);
      });
    } else {
      setHasInitialized(true);
    }
  }, [dispatch, defaultStore?.store_uid]);
  useEffect(() => {
    const syncCart = async () => {
      if (isAuthenticated && guestItems.length > 0 && defaultStore?.store_uid) {
        try {
          await dispatch(syncGuestCart({ guestItems, store_uid: defaultStore.store_uid })).unwrap();
          await dispatch(fetchBag(defaultStore.store_uid)).unwrap();
          success('Guest cart synced successfully!');
        } catch (err) {
          showError('Failed to sync guest cart');
        }
      }
    };
    syncCart();
  }, [isAuthenticated, guestItems.length, defaultStore, dispatch, success, showError]);
  const handleCartAction = useCallback(async (
    action: typeof incrementQuantity | typeof decrementQuantity | typeof removeFromCart,
    productUid: string, bagDetailId?: number, successMsg?: string
  ) => {
    if (!defaultStore?.store_uid) return;
    setIsUpdating(true);
    try {
      await dispatch(action({
        product_uid: productUid, bag_detail_id: bagDetailId,
        slug: 'CART', store_uid: defaultStore.store_uid,
      })).unwrap();
      if (!isGuest) await dispatch(fetchBag(defaultStore.store_uid)).unwrap();
      if (successMsg) success(successMsg);
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : (typeof err === 'string' ? err : 'Failed to update cart');
      showError(errorMessage);
    } finally {
      setIsUpdating(false);
    }
  }, [dispatch, defaultStore, isGuest, success, showError]);
  const handleIncrement = useCallback((uid: string, id?: number) => 
    handleCartAction(incrementQuantity, uid, id), [handleCartAction]);

  const handleDecrement = useCallback((uid: string, id?: number) => 
    handleCartAction(decrementQuantity, uid, id), [handleCartAction]);

  const handleRemove = useCallback((uid: string, id?: number) => 
    handleCartAction(removeFromCart, uid, id, 'Item removed from cart'), [handleCartAction]);
  const handleMoveToWishlist = useCallback(async (uid: string): Promise<void> => {
    if (!defaultStore?.store_uid || isGuest) {
      showError('Unable to move item to wishlist');
      return;
    }
    const cartItem = cartItems.find(item => item.product_uid === uid);
    if (!cartItem) {
      showError('Product not found in cart');
      return;
    }
    const product = 'zm_products' in cartItem ? cartItem.zm_products?.[0] : null;
    if (!product) {
      showError('Product details not found');
      return;
    }
    try {
      await dispatch(addToWishlist(product)).unwrap();
      await handleRemove(uid, 'bag_detail_id' in cartItem ? cartItem.bag_detail_id : undefined);
      success('Item moved to wishlist!');
    } catch {
      showError('Failed to move item to wishlist');
    }
  }, [cartItems, dispatch, handleRemove, isGuest, defaultStore, success, showError]);
  const handleCheckout = useCallback(() => {
    if (!cartItems.length) return showError('Your cart is empty');
    if (isGuest) return navigate('/login?redirect=/checkout');
    navigate('/checkout', { state: { appliedCoupon, pricing } });
  }, [cartItems.length, isGuest, navigate, appliedCoupon, pricing, showError]);

  return {
    cartItems, isGuest, loading, error, totalItems, isUpdating, hasInitialized,
    pricing, pricingSummary, totalSavings, potentialSavings, discountBreakdown,
    deliveryChargeInfo, deliveryCharge, deliveryChargeLoading, isFreeDeliveryEligible,
    appliedCoupon, appliedDiscount, availableCoupons, validCoupons, invalidCoupons,
    bestCoupon, couponsLoading, couponStats,
    handleIncrement, handleDecrement, handleRemove, handleMoveToWishlist, handleCheckout,
    handleApplyCoupon, handleApplyCouponDirect, handleRemoveCoupon, applyBestCoupon,
    previewDiscount, refreshCoupons, updateFilters, clearFilters, setSortBy,
    filterOptions, sortBy, formatCurrency, refreshDeliveryCharge,
  };
};

import { useCallback } from 'react';
import { useAppDispatch } from '../redux/useAppDispatch';
import { addToCart, incrementQuantity, decrementQuantity, removeFromCart } from '../../store/slices/cartSlice';
import { Product } from '../../types/api';
import { ProductDisplayData, createCartItem } from '../../utils/productUtils';
import { useToast } from '../ui/useToast';

interface UseCartActionsReturn {
  handleAddToCart: (product: Product, displayData: ProductDisplayData, quantity?: number) => Promise<boolean>;
  handleIncrementQuantity: (uid: string, id?: number) => Promise<boolean>;
  handleDecrementQuantity: (uid: string, id?: number) => Promise<boolean>;
  handleRemoveFromCart: (uid: string, id?: number) => Promise<boolean>;
}

export const useCartActions = (): UseCartActionsReturn => {
  const dispatch = useAppDispatch();
  const { success, error } = useToast();
  const handleAddToCart = useCallback(async (product: Product, displayData: ProductDisplayData, quantity?: number) => {
    try {
      await dispatch(addToCart(createCartItem(product, displayData, quantity || displayData.minOrderQuantity))).unwrap();
      success('Product added to cart!');
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to add product to cart';
      error(errorMessage);
      return false;
    }
  }, [dispatch, success, error]);
  const handleAction = useCallback(async (
    action: typeof incrementQuantity | typeof decrementQuantity | typeof removeFromCart,
    productUid: string, bagDetailId?: number, msg?: string
  ) => {
    try {
      await dispatch(action({ product_uid: productUid, bag_detail_id: bagDetailId })).unwrap();
      if (msg) success(msg);
      return true;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'Failed to update cart';
      error(errorMessage);
      return false;
    }
  }, [dispatch, success, error]);
  const handleIncrementQuantity = useCallback((uid: string, id?: number) => 
    handleAction(incrementQuantity, uid, id), [handleAction]);
  const handleDecrementQuantity = useCallback((uid: string, id?: number) => 
    handleAction(decrementQuantity, uid, id), [handleAction]);
  const handleRemoveFromCart = useCallback((uid: string, id?: number) => 
    handleAction(removeFromCart, uid, id, 'Product removed from cart'), [handleAction]);
  return { handleAddToCart, handleIncrementQuantity, handleDecrementQuantity, handleRemoveFromCart };
};

import { useState, useCallback, useMemo } from 'react';
import { BagDetail, CartItem as CartItemType, Product, ProductVariant, VariantAttribute } from '../../types/api';
import { DEFAULTS } from '../../utils/constants';
import { getCartItemInfo, getProductDetails, calculateItemPricing, checkStockAvailability } from '../../utils/cartHelpers';
import { useCurrencyFormatter } from '../../utils/currencyFormatter';

interface UseCartItemProps {
  item: BagDetail | CartItemType;
  isGuest: boolean;
  onIncrement: (productUid: string, bagDetailId?: number) => Promise<void>;
  onDecrement: (productUid: string, bagDetailId?: number) => Promise<void>;
  onRemove: (productUid: string, bagDetailId?: number) => Promise<void>;
  onMoveToWishlist?: (productUid: string) => Promise<void>;
  isUpdating?: boolean;
}

interface ItemPricing {
  price: number;
  mrp: number;
  discountPercent: number;
  totalPrice: number;
  totalMrp: number;
  savings: number;
}

interface StockInfo {
  stock: number;
  minOrderQuantity: number;
  isLowStock: boolean | undefined;
  isOutOfStock: boolean | undefined;
  canIncrement: boolean;
  canDecrement: boolean;
}

interface UseCartItemReturn {
  productUid: string;
  productCount: number;
  productInfo: { productName: string; productImage: string };
  pricing: ItemPricing;
  stockInfo: StockInfo;
  variantInfo: { variantId?: number | string; variantText?: string };
  isRemoving: boolean;
  isMovingToWishlist: boolean;
  isUpdating: boolean;
  isGuest: boolean;
  handleIncrement: () => Promise<void>;
  handleDecrement: () => Promise<void>;
  handleRemove: () => Promise<void>;
  handleMoveToWishlist: () => Promise<void>;
  formatCurrency: (amount: number) => string;
}

export const useCartItem = ({
  item, isGuest, onIncrement, onDecrement, onRemove, onMoveToWishlist, isUpdating = false,
}: UseCartItemProps): UseCartItemReturn => {
  const [isRemoving, setIsRemoving] = useState(false);
  const [isMovingToWishlist, setIsMovingToWishlist] = useState(false);
  const { formatCurrency } = useCurrencyFormatter();

  // Extract item info
  const itemInfo = getCartItemInfo(item);
  const { productUid, productCount, bagDetailId, product } = itemInfo;
  const details = getProductDetails(item);
  
  const productInfo = useMemo(() => ({ 
    productName: details.name, 
    productImage: details.image || DEFAULTS.PLACEHOLDER_IMAGE 
  }), [details.name, details.image]);

  const pricing = useMemo(() => calculateItemPricing(item), [item]);
  const stockInfo = useMemo(() => checkStockAvailability(item, DEFAULTS.LOW_STOCK_THRESHOLD), [item]);

  // Get variant info
  const variantInfo = useMemo(() => {
    const isBag = 'bag_detail_id' in item;
    const variantId = isBag ? item.product_variant_id : undefined;
    const variant = variantId && product?.product_variants?.find((v: ProductVariant) => v.id === variantId.toString());
    const variantText = variant && typeof variant === 'object' && variant.variant_attributes
      ? variant.variant_attributes.map((attr: VariantAttribute) => `${attr.zm_attribute.name}: ${attr.attribute_value}`).join(', ')
      : undefined;
    return { variantId, variantText };
  }, [item, product]);

  // Action handlers
  const handleIncrement = useCallback(async () => {
    if (stockInfo.canIncrement && !isUpdating) await onIncrement(productUid, bagDetailId);
  }, [stockInfo.canIncrement, isUpdating, onIncrement, productUid, bagDetailId]);

  const handleDecrement = useCallback(async () => {
    if (!isUpdating && stockInfo.canDecrement) await onDecrement(productUid, bagDetailId);
  }, [isUpdating, stockInfo.canDecrement, onDecrement, productUid, bagDetailId]);

  const handleRemove = useCallback(async () => {
    if (isRemoving) return;
    setIsRemoving(true);
    try { await onRemove(productUid, bagDetailId); } 
    finally { setIsRemoving(false); }
  }, [isRemoving, onRemove, productUid, bagDetailId]);

  const handleMoveToWishlist = useCallback(async (): Promise<void> => {
    if (!onMoveToWishlist || isMovingToWishlist) return;
    setIsMovingToWishlist(true);
    try { 
      await onMoveToWishlist(productUid); 
    } finally { 
      setIsMovingToWishlist(false); 
    }
  }, [onMoveToWishlist, isMovingToWishlist, productUid]);

  // Consolidated return object
  return {
    productUid, productCount, productInfo, pricing, stockInfo, variantInfo,
    isRemoving, isMovingToWishlist, isUpdating, isGuest,
    handleIncrement, handleDecrement, handleRemove, handleMoveToWishlist, formatCurrency,
  };
};

import { useState, useCallback, useMemo, useEffect, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAppDispatch, useAppSelector } from '../redux';
import { useToast } from '../ui/useToast';
import { fetchUserAddresses } from '../../store/slices/addressSlice';
import { fetchPaymentMethods, createOrder, setSelectedPaymentMethod, verifyRazorpayPayment } from '../../store/slices/orderSlice';
import { fetchDeliverySlots, setSelectedDate, setSelectedSlot } from '../../store/slices/deliverySlotSlice';
import { fetchBag } from '../../store/slices/cartSlice';
import { Address, PaymentMethod, DeliverySlot, CreateOrderBodyRequest, CreateOrderUserBagItem, CreateOrderResponse } from '../../types/api';
import { useCoupon } from './useCoupon';
import { usePricing } from './usePricing';
import { useDerivedCartItems } from '../../utils/cartDataHelpers';
import { decodeOrderDataFromUrl } from '../../utils/orderUtils';
import { DecodedOrderData, BagDetail, CartItem, Coupon } from '../../types/api';
import { CouponDiscountResult } from '../../utils/couponUtils';
import { DEFAULTS } from '../../utils/constants';

export type CheckoutStep = 'address' | 'delivery' | 'payment' | 'review' | 'confirmation';

interface UseCheckoutReturn {
  // Step management
  currentStep: CheckoutStep;
  goToNextStep: () => void;
  goToPreviousStep: () => void;
  goToStep: (step: CheckoutStep) => void;
  canProceedToNextStep: boolean;
  isFirstStep: boolean;
  isLastStep: boolean;
  stepIndex: number;
  totalSteps: number;
  availableSteps: CheckoutStep[];
  isDeliverySlotActive: boolean;

  // Address state
  addresses: Address[];
  selectedAddress: Address | null;
  addressLoading: boolean;
  addressError: string | null;
  setSelectedAddress: (address: Address | null) => void;
  refreshAddresses: () => void;

  // Delivery state
  deliverySlots: DeliverySlot[];
  selectedDeliveryDate: string | null;
  selectedDeliverySlot: DeliverySlot | null;
  deliveryLoading: boolean;
  deliveryError: string | null;
  setSelectedDeliveryDate: (date: string | null) => void;
  setSelectedDeliverySlot: (slot: DeliverySlot | null) => void;
  refreshDeliverySlots: () => void;

  // Payment state
  paymentMethods: PaymentMethod[];
  selectedPaymentMethod: PaymentMethod | null;
  paymentLoading: boolean;
  paymentError: string | null;
  setPaymentMethod: (method: PaymentMethod | null) => void;
  refreshPaymentMethods: () => void;

  // Cart & Pricing state
  cartItems: (BagDetail | CartItem)[];
  pricing: {
    subtotal: number;
    deliveryCharge: number;
    baseDeliveryCharge: number;
    deliveryDiscount: number;
    productDiscount: number;
    discount: number;
    tax: number;
    codCharge: number;
    total: number;
    isFreeDelivery: boolean;
  };
  pricingSummary: {
    subtotal: string;
    deliveryCharge: string;
    baseDeliveryCharge: string;
    deliveryDiscount: string;
    productDiscount: string;
    discount: string;
    tax: string;
    codCharge: string;
    total: string;
    savings: string;
  };
  appliedCoupon: Coupon | null;
  appliedDiscount: CouponDiscountResult | null;
  handleApplyCoupon: (code: string) => Promise<boolean>;
  handleRemoveCoupon: () => void;
  formatCurrency: (amount: number) => string;

  // Order state
  orderUid: string | null;
  orderLoading: boolean;
  orderError: string | null;
  orderConfirmationData: DecodedOrderData | null;

  // Actions
  handlePlaceOrder: () => Promise<void>;
  validateCurrentStep: () => boolean;
  resetCheckout: () => void;

  // Review state
  termsAccepted: boolean;
  setTermsAccepted: (accepted: boolean) => void;
}

// Memoized selector for better performance
const selectCheckoutData = (state: any) => ({
  isAuthenticated: state.auth.isAuthenticated,
  user: state.auth.user,
  addresses: state.address.addresses,
  addressLoading: state.address.loading,
  addressError: state.address.error,
  bags: state.cart.bags,
  guestItems: state.cart.guestItems,
  totalAmount: state.cart.totalAmount,
  defaultStore: state.store.defaultStore,
  defaultTenant: state.tenant.defaultTenant,
  deliverySlots: state.deliverySlot.availableSlots,
  reduxSelectedDate: state.deliverySlot.selectedDate,
  reduxSelectedSlot: state.deliverySlot.selectedSlot,
  deliveryLoading: state.deliverySlot.loading,
  deliveryError: state.deliverySlot.error,
  paymentMethods: state.order.paymentMethods,
  reduxSelectedPayment: state.order.selectedPaymentMethod,
  paymentMethodsState: state.order.paymentMethodsState,
  baseDeliveryCharge: state.deliveryCharge.deliveryCharge?.delivery_charge || 0,
  cartLoading: state.cart.loading,
});

export const useCheckout = (): UseCheckoutReturn => {
  const navigate = useNavigate();
  const dispatch = useAppDispatch();
  const { success, error: showError } = useToast();
  const razorpayInitialized = useRef(false);

  const {
    isAuthenticated, user, addresses, addressLoading, addressError,
    bags, guestItems, totalAmount, defaultStore, defaultTenant,
    deliverySlots, reduxSelectedDate, reduxSelectedSlot, deliveryLoading, deliveryError,
    paymentMethods, reduxSelectedPayment, paymentMethodsState, baseDeliveryCharge,
    cartLoading,
  } = useAppSelector(selectCheckoutData);

  const isDeliverySlotActive = useMemo(
    () => defaultTenant?.setting?.deliveryslot_management_active ?? false,
    [defaultTenant?.setting?.deliveryslot_management_active]
  );

  const STEP_ORDER = useMemo((): CheckoutStep[] => {
    const steps: CheckoutStep[] = ['address'];
    if (isDeliverySlotActive) steps.push('delivery');
    steps.push('payment', 'review', 'confirmation');
    return steps;
  }, [isDeliverySlotActive]);

  // Local state
  const [currentStep, setCurrentStep] = useState<CheckoutStep>('address');
  const [selectedAddress, setSelectedAddress] = useState<Address | null>(null);
  const [selectedDeliveryDate, setSelectedDeliveryDateLocal] = useState<string | null>(null);
  const [selectedDeliverySlot, setSelectedDeliverySlotLocal] = useState<DeliverySlot | null>(null);
  const [orderUid, setOrderUid] = useState<string | null>(null);
  const [orderLoading, setOrderLoading] = useState(false);
  const [orderError, setOrderError] = useState<string | null>(null);
  const [termsAccepted, setTermsAccepted] = useState(false);
  const [orderConfirmationData, setOrderConfirmationData] = useState<DecodedOrderData | null>(null);

  // Derived values - memoized for performance
  const isGuest = useMemo(() => !isAuthenticated, [isAuthenticated]);
  const cartItems = useDerivedCartItems(isGuest, guestItems, bags);
  const isOnlinePayment = useMemo(
    () => reduxSelectedPayment?.slug === 'razorpay' || reduxSelectedPayment?.slug === 'online',
    [reduxSelectedPayment?.slug]
  );
  const couponConfig = useMemo(() => ({
    isAuthenticated,
    userUid: user?.user_uid,
    cartTotal: totalAmount,
    deliveryCharge: baseDeliveryCharge,
    cartItems,
    isOnlinePayment,
  }), [isAuthenticated, user?.user_uid, totalAmount, baseDeliveryCharge, cartItems, isOnlinePayment]);

  const { appliedCoupon, appliedDiscount, handleApplyCoupon, handleRemoveCoupon } = useCoupon(couponConfig);

  const pricingConfig = useMemo(() => ({
    subtotal: totalAmount,
    appliedCoupon,
    appliedDiscount,
    storeUid: defaultStore?.store_uid,
    selectedPaymentMethod: reduxSelectedPayment,
  }), [totalAmount, appliedCoupon, appliedDiscount, defaultStore?.store_uid, reduxSelectedPayment]);

  const { pricing, pricingSummary, formatCurrency } = usePricing(pricingConfig);

  // Step management calculations
  const stepIndex = useMemo(() => STEP_ORDER.indexOf(currentStep), [STEP_ORDER, currentStep]);
  const isFirstStep = useMemo(() => stepIndex === 0, [stepIndex]);
  const isLastStep = useMemo(() => currentStep === 'confirmation', [currentStep]);
  const totalSteps = useMemo(() => STEP_ORDER.length - 1, [STEP_ORDER]);

  // Authentication check
  useEffect(() => {
    if (!isAuthenticated) {
      navigate('/login?redirect=/checkout');
    }
  }, [isAuthenticated, navigate]);

  // Fetch initial data on mount - optimized with single effect
  useEffect(() => {
    if (!isAuthenticated || !defaultStore?.store_uid) return;

    const fetchData = async () => {
      await Promise.all([
        dispatch(fetchUserAddresses()),
        dispatch(fetchPaymentMethods('B2C')),
        dispatch(fetchDeliverySlots({})),
        dispatch(fetchBag(defaultStore.store_uid)),
      ]);
    };

    fetchData();
  }, [dispatch, isAuthenticated, defaultStore?.store_uid]);

  // Redirect if cart is empty after data loads
  useEffect(() => {
    if (!cartLoading && cartItems.length === 0 && currentStep !== 'confirmation') {
      const timer = setTimeout(() => {
        showError('Your cart is empty');
        navigate('/');
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [cartLoading, cartItems.length, currentStep, navigate, showError]);

  // Auto-select default address
  useEffect(() => {
    if (addresses.length > 0 && !selectedAddress) {
      const defaultAddress = addresses.find((addr: Address) => addr.is_default) || addresses[0];
      setSelectedAddress(defaultAddress);
    }
  }, [addresses, selectedAddress]);

  // Auto-select default payment method
  useEffect(() => {
    if (paymentMethods.length > 0 && !reduxSelectedPayment) {
      dispatch(setSelectedPaymentMethod(paymentMethods[0]));
    }
  }, [paymentMethods, reduxSelectedPayment, dispatch]);

  // Validation logic - memoized callback
  const validateStep = useCallback((step: CheckoutStep, showErrorMsg = false): boolean => {
    let isValid = true;
    let msg = '';

    switch (step) {
      case 'address':
        isValid = !!selectedAddress;
        msg = 'Please select a delivery address';
        break;
      case 'delivery':
        isValid = !isDeliverySlotActive || !!(selectedDeliveryDate && selectedDeliverySlot);
        msg = 'Please select a delivery date and time slot';
        break;
      case 'payment':
        isValid = !!reduxSelectedPayment;
        msg = 'Please select a payment method';
        break;
      case 'review':
        if (cartItems.length === 0) {
          isValid = false;
          msg = 'Your cart is empty';
        } else if (!termsAccepted) {
          isValid = false;
          msg = 'Please accept the terms and conditions';
        } else {
          const baseValid = !!selectedAddress && !!reduxSelectedPayment;
          isValid = isDeliverySlotActive 
            ? baseValid && !!selectedDeliveryDate && !!selectedDeliverySlot
            : baseValid;
          msg = 'Please complete all required steps';
        }
        break;
      default:
        isValid = true;
    }

    if (!isValid && showErrorMsg && msg) showError(msg);
    return isValid;
  }, [selectedAddress, selectedDeliveryDate, selectedDeliverySlot, reduxSelectedPayment, 
      cartItems.length, isDeliverySlotActive, showError, termsAccepted]);

  const validateCurrentStep = useCallback(() => validateStep(currentStep, true), [currentStep, validateStep]);
  const canProceedToNextStep = useMemo(() => validateStep(currentStep, false), [currentStep, validateStep]);

  // Step navigation callbacks
  const goToNextStep = useCallback(() => {
    if (!validateCurrentStep()) return;

    const nextIndex = stepIndex + 1;
    if (nextIndex < STEP_ORDER.length - 1) {
      setCurrentStep(STEP_ORDER[nextIndex]);
    }
  }, [stepIndex, validateCurrentStep, STEP_ORDER]);

  const goToPreviousStep = useCallback(() => {
    if (isFirstStep) return;
    const prevIndex = stepIndex - 1;
    setCurrentStep(STEP_ORDER[prevIndex]);
  }, [stepIndex, isFirstStep, STEP_ORDER]);

  const goToStep = useCallback((step: CheckoutStep) => {
    setCurrentStep(step);
  }, []);

  // Data refresh callbacks
  const refreshAddresses = useCallback(() => { 
    if (isAuthenticated) {
      dispatch(fetchUserAddresses());
    }
  }, [dispatch, isAuthenticated]);

  const handleSetSelectedDeliveryDate = useCallback((date: string | null) => {
    setSelectedDeliveryDateLocal(date);
    dispatch(setSelectedDate(date));
    setSelectedDeliverySlotLocal(null);
    dispatch(setSelectedSlot(null));
  }, [dispatch]);

  const handleSetSelectedDeliverySlot = useCallback((slot: DeliverySlot | null) => {
    setSelectedDeliverySlotLocal(slot);
    dispatch(setSelectedSlot(slot));
  }, [dispatch]);

  const refreshDeliverySlots = useCallback(() => {
    dispatch(fetchDeliverySlots({}));
  }, [dispatch]);

  const handleSetPaymentMethod = useCallback((method: PaymentMethod | null) => { 
    if (method) {
      dispatch(setSelectedPaymentMethod(method));
    }
  }, [dispatch]);

  const refreshPaymentMethods = useCallback(() => {
    dispatch(fetchPaymentMethods('B2C'));
  }, [dispatch]);

  // Handle order confirmation and redirect
  const handleOrderConfirmation = useCallback(async (result: CreateOrderResponse) => {
    try {
      // Decode order data from URL
      if (result.urlLink) {
        const decodedData = decodeOrderDataFromUrl(result.urlLink);
        if (decodedData) {
          setOrderConfirmationData(decodedData);
          console.log('📦 Order confirmation data decoded:', decodedData);
        }
      }

      // Refresh cart to clear items
      if (defaultStore?.store_uid) {
        await dispatch(fetchBag(defaultStore.store_uid)).unwrap();
      }

      success('Order placed successfully!');
      setCurrentStep('confirmation');
    } catch (error) {
      console.error('Error in order confirmation:', error);
      showError('Order placed but failed to refresh cart');
      setCurrentStep('confirmation');
    }
  }, [defaultStore?.store_uid, dispatch, success, showError]);

  // Handle Razorpay payment
  const handleRazorpayPayment = useCallback((orderData: CreateOrderResponse, paymentSlug: string) => {
    // Check if Razorpay is loaded
    if (typeof window.Razorpay === 'undefined') {
      showError('Payment gateway not loaded. Please refresh and try again.');
      setOrderLoading(false);
      return;
    }

    const rzpKey = defaultTenant?.setting?.razorpay_public_token || '';
    const payOrderId = orderData.data.id || '';

    const options = {
      key: rzpKey,
      amount: pricing.total * 100,
      currency: DEFAULTS.CURRENCY_NAME,
      order_id: payOrderId,
      description: 'Payment for product',
      handler: async (response: {
        razorpay_order_id: string;
        razorpay_payment_id: string;
        razorpay_signature: string;
      }) => {
        try {
          console.log('🚀 Razorpay payment response:', response);

          const verificationResult = await dispatch(verifyRazorpayPayment({
            razorpay_order_id: response.razorpay_order_id,
            razorpay_payment_id: response.razorpay_payment_id,
            razorpay_signature: response.razorpay_signature,
            slug: paymentSlug,
          })).unwrap();

          console.log('🚀 Razorpay verification result:', verificationResult);

          if (verificationResult.success) {
            await handleOrderConfirmation(orderData);
          } else {
            showError(verificationResult.data?.message || 'Payment verification failed');
            setOrderLoading(false);
          }
        } catch (error) {
          const errorMsg = error instanceof Error ? error.message : 'Payment verification failed';
          showError(errorMsg);
          setOrderLoading(false);
        }
      },
      modal: {
        ondismiss: () => {
          showError('Payment cancelled');
          setOrderLoading(false);
        },
      },
    };

    const razorpayInstance = new window.Razorpay(options);

    razorpayInstance.on('payment.failed', () => {
      showError(DEFAULTS.RAZOR_PAYMENT_FAILED_MESSAGE || 'Payment failed');
      setOrderLoading(false);
    });

    razorpayInstance.open();
  }, [defaultTenant?.setting?.razorpay_public_token, pricing.total, dispatch, showError, handleOrderConfirmation]);
  // Build user bag items for order
  const buildUserBagItems = useCallback((items: (BagDetail | CartItem)[]): CreateOrderUserBagItem[] => {
    return items.map(item => {
      const isBag = 'bag_detail_id' in item;
      const product = isBag ? item.zm_products?.[0] : null;

      return {
        product_uid: item.product_uid,
        stock: isBag ? product?.stock?.toString() || null : item.stock?.toString() || null,
        product_count: item.product_count,
        price: isBag ? item.selling_price.toString() : item.price,
        track_inventory: isBag ? product?.track_inventory || false : item.track_inventory,
        product_status: isBag ? product?.product_status || true : item.product_status,
        category_uid: isBag ? product?.category_uid || '' : item.category_uid,
        min_order_quantity: isBag ? product?.min_order_quantity || null : item.min_order_quantity || null,
      };
    });
  }, []);

  // Handle place order
  const handlePlaceOrder = useCallback(async () => {
    if (!validateCurrentStep()) return;

    // Validate required fields
    const requiredFields = isDeliverySlotActive
      ? [selectedAddress, selectedDeliveryDate, selectedDeliverySlot, reduxSelectedPayment, defaultStore?.store_uid]
      : [selectedAddress, reduxSelectedPayment, defaultStore?.store_uid];

    if (requiredFields.some(field => !field)) {
      showError('Missing required information for order placement');
      return;
    }

    setOrderLoading(true);
    setOrderError(null);

    try {
      const userBag = buildUserBagItems(cartItems);

      const orderRequest: CreateOrderBodyRequest = {
        // Pricing details
        cod_charge: reduxSelectedPayment?.slug === 'cod' ? pricing.codCharge || 0 : 0,
        coupon_amount: appliedDiscount?.discountAmount || 0,
        delivery_charge: pricing.deliveryCharge,
        discount_amount: !!appliedDiscount,
        discount_percent: appliedCoupon?.coupon_percentage || 0,
        final_price: pricing.total,
        price: pricing.subtotal,

        // Order metadata
        slugData: 'CART',
        userBag,
        buyer_gst_number: null,
        checkout_flag: 1,
        customer_type_id: 1,

        // Delivery details
        dayName: isDeliverySlotActive && selectedDeliverySlot ? (selectedDeliverySlot.dayName || '') : '',
        delivery_address_id: selectedAddress!.b2c_address_id,
        delivery_date: isDeliverySlotActive && selectedDeliveryDate ? selectedDeliveryDate : '',
        delivery_time: isDeliverySlotActive && selectedDeliverySlot ? (selectedDeliverySlot.delivery_time || '') : '',
        order_notes: null,

        // Payment details
        payment_method_id: reduxSelectedPayment!.payment_method_id,
        secured: true,
        slug: reduxSelectedPayment!.slug,
        store_uid: defaultStore!.store_uid,
      };

      const result = await dispatch(createOrder(orderRequest)).unwrap();
      console.log('🚀 Order creation result:', result);

      if (!result?.order_uid) {
        throw new Error('Order creation failed - no order UID returned');
      }

      setOrderUid(result.order_uid);

      // Handle payment based on method
      if (reduxSelectedPayment?.slug === 'razorpay') {
        handleRazorpayPayment(result, reduxSelectedPayment.slug);
      } else {
        await handleOrderConfirmation(result);
        setOrderLoading(false);
      }
    } catch (error) {
      const errorMessage = error instanceof Error 
        ? error.message 
        : 'Failed to place order. Please try again.';

      console.error('Order placement error:', error);
      setOrderError(errorMessage);
      showError(errorMessage);
      setOrderLoading(false);
    }
  }, [
    validateCurrentStep,
    selectedAddress,
    selectedDeliveryDate,
    selectedDeliverySlot,
    reduxSelectedPayment,
    defaultStore,
    cartItems,
    appliedDiscount,
    appliedCoupon,
    pricing,
    dispatch,
    showError,
    isDeliverySlotActive,
    buildUserBagItems,
    handleRazorpayPayment,
    handleOrderConfirmation,
  ]);
  // Reset checkout state
  const resetCheckout = useCallback(() => {
    setCurrentStep('address');
    setSelectedAddress(null);
    setSelectedDeliveryDateLocal(null);
    setSelectedDeliverySlotLocal(null);
    setOrderUid(null);
    setOrderError(null);
    setTermsAccepted(false);
    setOrderConfirmationData(null);
    dispatch(setSelectedDate(null));
    dispatch(setSelectedSlot(null));
  }, [dispatch]);

  // Return all checkout functionality
  return useMemo(() => ({
    // Step management
    currentStep,
    goToNextStep,
    goToPreviousStep,
    goToStep,
    canProceedToNextStep,
    isFirstStep,
    isLastStep,
    stepIndex,
    totalSteps,
    availableSteps: STEP_ORDER,
    isDeliverySlotActive,

    // Address management
    addresses,
    selectedAddress,
    addressLoading,
    addressError,
    setSelectedAddress,
    refreshAddresses,

    // Delivery management
    deliverySlots,
    selectedDeliveryDate: selectedDeliveryDate || reduxSelectedDate,
    selectedDeliverySlot: selectedDeliverySlot || reduxSelectedSlot,
    deliveryLoading,
    deliveryError,
    setSelectedDeliveryDate: handleSetSelectedDeliveryDate,
    setSelectedDeliverySlot: handleSetSelectedDeliverySlot,
    refreshDeliverySlots,

    // Payment management
    paymentMethods,
    selectedPaymentMethod: reduxSelectedPayment,
    paymentLoading: paymentMethodsState.loading,
    paymentError: paymentMethodsState.error,
    setPaymentMethod: handleSetPaymentMethod,
    refreshPaymentMethods,

    // Cart & Pricing
    cartItems,
    pricing,
    pricingSummary,
    appliedCoupon,
    appliedDiscount,
    handleApplyCoupon,
    handleRemoveCoupon,
    formatCurrency,

    // Order management
    orderUid,
    orderLoading,
    orderError,
    orderConfirmationData,
    handlePlaceOrder,
    validateCurrentStep,
    resetCheckout,

    // Review state
    termsAccepted,
    setTermsAccepted,
  }), [
    currentStep, goToNextStep, goToPreviousStep, goToStep, canProceedToNextStep,
    isFirstStep, isLastStep, stepIndex, totalSteps, STEP_ORDER, isDeliverySlotActive,
    addresses, selectedAddress, addressLoading, addressError, refreshAddresses,
    deliverySlots, selectedDeliveryDate, reduxSelectedDate, selectedDeliverySlot, reduxSelectedSlot,
    deliveryLoading, deliveryError, handleSetSelectedDeliveryDate, handleSetSelectedDeliverySlot, refreshDeliverySlots,
    paymentMethods, reduxSelectedPayment, paymentMethodsState.loading, paymentMethodsState.error,
    handleSetPaymentMethod, refreshPaymentMethods,
    cartItems, pricing, pricingSummary, appliedCoupon, appliedDiscount,
    handleApplyCoupon, handleRemoveCoupon, formatCurrency,
    orderUid, orderLoading, orderError, orderConfirmationData,
    handlePlaceOrder, validateCurrentStep, resetCheckout,
    termsAccepted,
  ]);
};

import { useState, useCallback, useEffect, useMemo, useRef } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { fetchUserCoupons, setAppliedCoupon as setReduxAppliedCoupon, clearAppliedCoupon } from '../../store/slices/couponSlice';
import { useToast } from '../ui/useToast';
import { UserCoupon, CartItem, BagDetail } from '../../types/api';
import {
  validateCoupon,
  calculateCouponDiscount,
  selectBestCoupon,
  filterCoupons,
  sortCoupons,
  toUnifiedCartItem,
  CouponFilterOptions,
  CouponSortBy,
  CouponDiscountResult,
  UnifiedCartItem,
} from '../../utils/couponUtils';

interface UseCouponProps {
  isAuthenticated: boolean;
  userUid?: string;
  cartTotal: number;
  deliveryCharge: number;
  cartItems: (CartItem | BagDetail)[];
  isOnlinePayment?: boolean;
}

interface CouponValidationResult {
  isValid: boolean;
  message?: string;
  reason?: 'expired' | 'not_started' | 'inactive' | 'usage_limit' | 'min_order' | 'no_eligible_items' | 'payment_restriction';
}

interface InvalidCouponInfo {
  coupon: UserCoupon;
  validation: CouponValidationResult;
}

interface UseCouponReturn {
  // State
  appliedCoupon: UserCoupon | null;
  appliedDiscount: CouponDiscountResult | null;
  availableCoupons: UserCoupon[];
  validCoupons: UserCoupon[];
  invalidCoupons: InvalidCouponInfo[];
  bestCoupon: { coupon: UserCoupon | null; savings: number; discount: CouponDiscountResult | null };
  couponsLoading: boolean;
  couponStats: {
    total: number;
    valid: number;
    invalid: number;
    bestSavings: number;
    appliedSavings: number;
  };
  autoApplyBest: boolean;
  
  // Filters & Sorting
  filterOptions: CouponFilterOptions;
  sortBy: CouponSortBy;
  updateFilters: (options: Partial<CouponFilterOptions>) => void;
  clearFilters: () => void;
  setSortBy: (sortBy: CouponSortBy) => void;
  setAutoApplyBest: (value: boolean) => void;
  
  // Functions
  handleApplyCoupon: (couponCode: string) => Promise<boolean>;
  handleApplyCouponDirect: (coupon: UserCoupon) => Promise<boolean>;
  handleRemoveCoupon: () => void;
  applyBestCoupon: () => void;
  previewDiscount: (coupon: UserCoupon) => CouponDiscountResult | null;
  refreshCoupons: () => void;
  
  // Utilities
  validateCoupon: (coupon: UserCoupon) => CouponValidationResult;
  calculateDiscount: (coupon: UserCoupon) => CouponDiscountResult;
}

export const useCoupon = ({
  cartTotal,
  deliveryCharge,
  cartItems,
  isOnlinePayment = false,
}: UseCouponProps): UseCouponReturn => {
  const dispatch = useAppDispatch();
  const { success, error: showError } = useToast();

  // Redux state
  const { availableCoupons, loading: couponsLoading, appliedCoupon } = useAppSelector((state) => state.coupon);

  // Local state
  const [appliedDiscount, setAppliedDiscount] = useState<CouponDiscountResult | null>(null);
  const [filterOptions, setFilterOptions] = useState<CouponFilterOptions>({});
  const [sortBy, setSortBy] = useState<CouponSortBy>('discount_desc');
  const [autoApplyBest, setAutoApplyBest] = useState(false);

  // Convert cart items to unified format
  const unifiedCartItems = useMemo(() => cartItems.map(toUnifiedCartItem), [cartItems]);

  // Stable reference for cart items to prevent infinite loops
  const cartItemsKey = useMemo(() => 
    JSON.stringify(cartItems.map(item => ({
      uid: 'bag_detail_id' in item ? item.product_uid : item.product_uid,
      count: item.product_count,
      price: 'bag_detail_id' in item ? item.selling_price : item.price
    })))
  , [cartItems]);

  // Fetch coupons
  useEffect(() => {
    dispatch(fetchUserCoupons());
  }, [dispatch]);

  // Calculate and validate discount
  useEffect(() => {
    if (!appliedCoupon) {
      if (appliedDiscount) setAppliedDiscount(null);
      return;
    }

    const discount = calculateCouponDiscount(appliedCoupon, cartTotal, deliveryCharge, unifiedCartItems);
    
    if (cartTotal > 0) {
      const validation = validateCoupon(appliedCoupon, cartTotal, unifiedCartItems, isOnlinePayment);
      if (!validation.isValid) {
        dispatch(clearAppliedCoupon());
        setAppliedDiscount(null);
        showError(validation.message || 'Applied coupon is no longer valid');
      } else {
        setAppliedDiscount(discount);
      }
    } else {
      setAppliedDiscount(discount);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [appliedCoupon, cartTotal, deliveryCharge, cartItemsKey, isOnlinePayment, dispatch, showError]);

  // Filter and sort coupons
  const processedCoupons = useMemo(() => {
    let processed = filterCoupons(availableCoupons, filterOptions);
    processed = sortCoupons(processed, sortBy, cartTotal, deliveryCharge, unifiedCartItems);
    return processed;
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [availableCoupons, filterOptions, sortBy, cartTotal, deliveryCharge, cartItemsKey]);

  // Valid coupons (that pass validation)
  const validCoupons = useMemo(() => {
    return processedCoupons.filter(coupon => {
      const validation = validateCoupon(coupon, cartTotal, unifiedCartItems, isOnlinePayment);
      return validation.isValid;
    });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [processedCoupons, cartTotal, cartItemsKey, isOnlinePayment]);

  // Invalid coupons with reasons
  const invalidCoupons = useMemo(() => {
    return processedCoupons
      .map(coupon => {
        const validation = validateCoupon(coupon, cartTotal, unifiedCartItems, isOnlinePayment);
        if (!validation.isValid) {
          return { coupon, validation };
        }
        return null;
      })
      .filter((item): item is InvalidCouponInfo => item !== null);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [processedCoupons, cartTotal, cartItemsKey, isOnlinePayment]);

  // Best coupon suggestion
  const bestCoupon = useMemo(() => {
    return selectBestCoupon(
      availableCoupons,
      cartTotal,
      deliveryCharge,
      unifiedCartItems,
      isOnlinePayment
    );
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [availableCoupons, cartTotal, deliveryCharge, cartItemsKey, isOnlinePayment]);

  // Track if we've already auto-applied to prevent re-application
  const hasAutoAppliedRef = useRef(false);

  // Auto-apply best coupon if enabled
  useEffect(() => {
    if (autoApplyBest && bestCoupon.coupon && bestCoupon.discount && !appliedCoupon && !hasAutoAppliedRef.current) {
      hasAutoAppliedRef.current = true;
      dispatch(setReduxAppliedCoupon({ 
        coupon: bestCoupon.coupon, 
        discount: bestCoupon.discount.discountAmount 
      }));
      setAppliedDiscount(bestCoupon.discount);
      success(`Best coupon ${bestCoupon.coupon.coupon_code} applied automatically!`);
    }
    
    // Reset flag when coupon is removed or auto-apply is disabled
    if (!autoApplyBest || appliedCoupon) {
      hasAutoAppliedRef.current = false;
    }
  }, [autoApplyBest, bestCoupon, appliedCoupon, success, dispatch]);

  // Calculate discount for specific coupon (preview)
  const previewDiscount = useCallback(
    (coupon: UserCoupon): CouponDiscountResult | null => {
      const validation = validateCoupon(coupon, cartTotal, unifiedCartItems, isOnlinePayment);
      if (!validation.isValid) return null;

      return calculateCouponDiscount(coupon, cartTotal, deliveryCharge, unifiedCartItems);
    },
    [cartTotal, deliveryCharge, unifiedCartItems, isOnlinePayment]
  );

  // Coupon application logic
  const applyCouponLogic = useCallback((coupon: UserCoupon) => {
    const validation = validateCoupon(coupon, cartTotal, unifiedCartItems, isOnlinePayment);
    if (!validation.isValid) {
      showError(validation.message || 'Invalid coupon');
      return false;
    }

    const discount = calculateCouponDiscount(coupon, cartTotal, deliveryCharge, unifiedCartItems);
    dispatch(setReduxAppliedCoupon({ coupon, discount: discount.discountAmount }));
    setAppliedDiscount(discount);
    
    success(coupon.coupon_type === 'free-shipping'
      ? `${coupon.coupon_code} applied! Free shipping activated.`
      : `${coupon.coupon_code} applied! You save ₹${discount.discountAmount.toFixed(2)}`);
    return true;
  }, [cartTotal, deliveryCharge, unifiedCartItems, isOnlinePayment, success, showError, dispatch]);

  // Handle coupon application by code
  const handleApplyCoupon = useCallback(
    async (couponCode: string): Promise<boolean> => {
      if (!couponCode?.trim()) {
        showError('Please enter a coupon code');
        return false;
      }

      const coupon = availableCoupons.find(c => c.coupon_code.toUpperCase() === couponCode.toUpperCase());
      if (!coupon) {
        showError('Invalid coupon code');
        return false;
      }

      if (appliedCoupon?.coupon_uid === coupon.coupon_uid) {
        showError('This coupon is already applied');
        return false;
      }

      return applyCouponLogic(coupon);
    },
    [availableCoupons, appliedCoupon, showError, applyCouponLogic]
  );

  // Handle coupon application by object
  const handleApplyCouponDirect = useCallback(
    async (coupon: UserCoupon): Promise<boolean> => {
      if (appliedCoupon?.coupon_uid === coupon.coupon_uid) {
        showError('This coupon is already applied');
        return false;
      }
      return applyCouponLogic(coupon);
    },
    [appliedCoupon, showError, applyCouponLogic]
  );

  // Handle coupon removal
  const handleRemoveCoupon = useCallback(() => {
    dispatch(clearAppliedCoupon());
    setAppliedDiscount(null);
    success(appliedCoupon?.coupon_type === 'free-shipping'
      ? 'Coupon removed. Delivery charge restored.'
      : 'Coupon removed');
  }, [appliedCoupon, success, dispatch]);

  // Apply best coupon
  const applyBestCoupon = useCallback(() => {
    bestCoupon.coupon ? handleApplyCouponDirect(bestCoupon.coupon) : showError('No valid coupons available');
  }, [bestCoupon, handleApplyCouponDirect, showError]);

  // Filter and refresh actions
  const updateFilters = useCallback((options: Partial<CouponFilterOptions>) => 
    setFilterOptions(prev => ({ ...prev, ...options })), []);
  const clearFilters = useCallback(() => setFilterOptions({}), []);
  const refreshCoupons = useCallback(() => dispatch(fetchUserCoupons()), [dispatch]);

  // Get coupon statistics
  const couponStats = useMemo(() => ({
    total: availableCoupons.length,
    valid: validCoupons.length,
    invalid: invalidCoupons.length,
    bestSavings: bestCoupon.savings,
    appliedSavings: appliedDiscount?.discountAmount || 0,
  }), [availableCoupons, validCoupons, invalidCoupons, bestCoupon, appliedDiscount]);

  // Consolidated return object
  return {
    // State
    appliedCoupon, appliedDiscount, availableCoupons: processedCoupons,
    validCoupons, invalidCoupons, bestCoupon, couponsLoading, couponStats, autoApplyBest,

    // Filters & Sorting
    filterOptions, sortBy, updateFilters, clearFilters, setSortBy, setAutoApplyBest,

    // Functions
    handleApplyCoupon, handleApplyCouponDirect, handleRemoveCoupon,
    applyBestCoupon, previewDiscount, refreshCoupons,

    // Utilities
    validateCoupon: (coupon: UserCoupon) => validateCoupon(coupon, cartTotal, unifiedCartItems, isOnlinePayment),
    calculateDiscount: (coupon: UserCoupon) => calculateCouponDiscount(coupon, cartTotal, deliveryCharge, unifiedCartItems),
  };
};

import { useState, useCallback, useMemo } from 'react';
import { UserCoupon } from '../../types/api';
import { CouponDiscountResult } from '../../utils/couponUtils';

interface UseCouponInputProps {
  availableCoupons: UserCoupon[];
  validCoupons: UserCoupon[];
  invalidCoupons: Array<{ coupon: UserCoupon; validation: { message?: string } }>;
  appliedCoupon: UserCoupon | null;
  appliedDiscount: CouponDiscountResult | null;
  bestCoupon: { coupon: UserCoupon | null; savings: number };
  onApplyCoupon: (couponCode: string) => Promise<boolean>;
  onApplyCouponDirect: (coupon: UserCoupon) => Promise<boolean>;
  onRemoveCoupon: () => void;
  onApplyBestCoupon: () => void;
  isLoading?: boolean;
  cartTotal: number;
}

interface UseCouponInputReturn {
  couponCode: string;
  error: string | null;
  isApplying: boolean;
  showAllCoupons: boolean;
  searchQuery: string;
  filterType: string;
  showFilters: boolean;
  filteredValidCoupons: UserCoupon[];
  minAmountNeeded: number;
  handleApplyCoupon: () => Promise<void>;
  handleRemoveCoupon: () => void;
  handleSelectCoupon: (coupon: UserCoupon) => Promise<void>;
  handleCouponCodeChange: (value: string) => void;
  handleSearchChange: (value: string) => void;
  handleFilterTypeChange: (type: string) => void;
  toggleShowAllCoupons: () => void;
  toggleShowFilters: () => void;
}

export const useCouponInput = ({
  validCoupons, invalidCoupons, onApplyCoupon, onApplyCouponDirect, onRemoveCoupon, cartTotal,
}: UseCouponInputProps): UseCouponInputReturn => {
  const [couponCode, setCouponCode] = useState('');
  const [error, setError] = useState<string | null>(null);
  const [isApplying, setIsApplying] = useState(false);
  const [showAllCoupons, setShowAllCoupons] = useState(false);
  const [searchQuery, setSearchQuery] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [showFilters, setShowFilters] = useState(false);
  const handleApplyCoupon = useCallback(async () => {
    if (!couponCode.trim()) return setError('Please enter a coupon code');
    setIsApplying(true);
    setError(null);
    try {
      const success = await onApplyCoupon(couponCode.trim().toUpperCase());
      if (success) setCouponCode('');
      else setError('Invalid or expired coupon code');
    } catch {
      setError('Failed to apply coupon');
    } finally {
      setIsApplying(false);
    }
  }, [couponCode, onApplyCoupon]);
  const handleRemoveCoupon = useCallback(() => {
    onRemoveCoupon();
    setError(null);
  }, [onRemoveCoupon]);
  const handleSelectCoupon = useCallback(async (coupon: UserCoupon) => {
    setCouponCode(coupon.coupon_code);
    setIsApplying(true);
    setError(null);
    try {
      if (!await onApplyCouponDirect(coupon)) setError('Failed to apply coupon');
    } catch {
      setError('Failed to apply coupon');
    } finally {
      setIsApplying(false);
    }
  }, [onApplyCouponDirect]);
  const filteredValidCoupons = useMemo(() => {
    let filtered = validCoupons;
    if (searchQuery.trim()) {
      const query = searchQuery.toLowerCase();
      filtered = filtered.filter(c => 
        c.coupon_code.toLowerCase().includes(query) || c.description.toLowerCase().includes(query)
      );
    }
    if (filterType !== 'all') {
      filtered = filtered.filter(c => c.coupon_type === filterType);
    }
    return filtered;
  }, [validCoupons, searchQuery, filterType]);
  const handleCouponCodeChange = useCallback((value: string) => {
    setCouponCode(value.toUpperCase());
    setError(null);
  }, []);
  const handleSearchChange = useCallback((value: string) => setSearchQuery(value), []);
  const handleFilterTypeChange = useCallback((type: string) => setFilterType(type), []);
  const toggleShowAllCoupons = useCallback(() => setShowAllCoupons(p => !p), []);
  const toggleShowFilters = useCallback(() => setShowFilters(p => !p), []);
  const minAmountNeeded = useMemo(() => {
    if (!invalidCoupons.length) return 0;
    return Math.max(0, Math.max(...invalidCoupons.map(({ coupon }) => coupon.discount_offer)) - cartTotal);
  }, [invalidCoupons, cartTotal]);
  return {
    couponCode, error, isApplying, showAllCoupons, searchQuery, filterType, showFilters,
    filteredValidCoupons, minAmountNeeded, handleApplyCoupon, handleRemoveCoupon, 
    handleSelectCoupon, handleCouponCodeChange, handleSearchChange, handleFilterTypeChange, 
    toggleShowAllCoupons, toggleShowFilters,
  };
};

import { useEffect, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { getDeliveryCharge } from '../../store/slices/deliveryChargeSlice';
import { UserCoupon, DeliveryCharge } from '../../types/api';
import { CouponDiscountResult } from '../../utils/couponUtils';
import { useCurrencyFormatter } from '../../utils/currencyFormatter';

interface UsePricingProps {
  subtotal: number;
  appliedCoupon: UserCoupon | null;
  appliedDiscount: CouponDiscountResult | null;
  storeUid?: string;
  selectedPaymentMethod?: { slug: string } | null;
}

interface PricingInfo {
  subtotal: number;
  deliveryCharge: number;
  baseDeliveryCharge: number;
  deliveryDiscount: number;
  productDiscount: number;
  discount: number;
  tax: number;
  codCharge: number;
  total: number;
  couponApplied: boolean;
  isFreeDelivery: boolean;
}

interface PricingSummaryInfo {
  subtotal: string;
  deliveryCharge: string;
  baseDeliveryCharge: string;
  deliveryDiscount: string;
  productDiscount: string;
  discount: string;
  tax: string;
  codCharge: string;
  total: string;
  savings: string;
}

interface DeliveryChargeInfo {
  baseCharge: number;
  finalCharge: number;
  saved: number;
  isFree: boolean;
  hasDiscount: boolean;
}

interface UsePricingReturn {
  pricing: PricingInfo;
  pricingSummary: PricingSummaryInfo;
  totalSavings: number;
  potentialSavings: number;
  discountBreakdown: Array<{ label: string; amount: number }>;
  deliveryChargeInfo: DeliveryChargeInfo;
  deliveryCharge: DeliveryCharge | null;
  deliveryChargeLoading: boolean;
  isFreeDeliveryEligible: boolean;
  formatCurrency: (amount: number) => string;
  refreshDeliveryCharge: () => void;
}

export const usePricing = ({ subtotal, appliedCoupon, appliedDiscount, storeUid, selectedPaymentMethod }: UsePricingProps): UsePricingReturn => {
  const dispatch = useAppDispatch();
  const { deliveryCharge, loading: deliveryChargeLoading } = useAppSelector((state) => state.deliveryCharge);
  const codChargeAmount = useAppSelector((state) => state.tenant.defaultTenant?.setting?.cod_charge || 0);
  const { formatCurrency } = useCurrencyFormatter();
  useEffect(() => {
    if (storeUid) dispatch(getDeliveryCharge(storeUid));
  }, [dispatch, storeUid]);
  const pricing = useMemo(() => {
    const baseDeliveryFee = deliveryCharge?.delivery_charge || 0;
    const deliveryDiscount = Math.min(appliedDiscount?.deliveryDiscount || 0, baseDeliveryFee);
    const finalDeliveryCharge = Math.max(0, baseDeliveryFee - deliveryDiscount);
    const totalDiscount = appliedDiscount?.discountAmount || 0;
    const productDiscount = totalDiscount - deliveryDiscount;
    const isCOD = selectedPaymentMethod?.slug === 'cod';
    const codCharge = isCOD ? codChargeAmount : 0;
    const total = Math.max(0, subtotal - productDiscount + finalDeliveryCharge + codCharge);
    return {
      subtotal, deliveryCharge: finalDeliveryCharge, baseDeliveryCharge: baseDeliveryFee,
      deliveryDiscount, productDiscount, discount: totalDiscount, tax: 0, codCharge, total,
      couponApplied: !!appliedCoupon, isFreeDelivery: finalDeliveryCharge === 0 && baseDeliveryFee > 0,
    };
  }, [subtotal, deliveryCharge, appliedCoupon, appliedDiscount, selectedPaymentMethod, codChargeAmount]);
  const totalSavings = pricing.discount;
  const isFreeDeliveryEligible = pricing.isFreeDelivery;
  const discountBreakdown = useMemo(() => {
    if (!appliedDiscount) return [];
    const breakdown: Array<{ label: string; amount: number }> = [];
    appliedDiscount.productDiscounts.forEach((discount) => 
      breakdown.push({ label: 'Product Discount', amount: discount }));
    appliedDiscount.categoryDiscounts.forEach((discount) => 
      breakdown.push({ label: 'Category Discount', amount: discount }));
    if (appliedDiscount.couponType === 'amount-cut-off' && pricing.productDiscount > 0) {
      breakdown.push({ label: 'Cart Discount', amount: pricing.productDiscount });
    }
    if (appliedDiscount.deliveryDiscount > 0) {
      breakdown.push({ label: 'Free Delivery', amount: appliedDiscount.deliveryDiscount });
    }
    return breakdown;
  }, [appliedDiscount, pricing.productDiscount]);
  const deliveryChargeInfo = useMemo(() => ({
    baseCharge: pricing.baseDeliveryCharge, finalCharge: pricing.deliveryCharge,
    saved: pricing.deliveryDiscount, isFree: pricing.deliveryCharge === 0 && pricing.baseDeliveryCharge > 0,
    hasDiscount: pricing.deliveryDiscount > 0,
  }), [pricing]);
  const pricingSummary = useMemo(() => ({
    subtotal: formatCurrency(pricing.subtotal), deliveryCharge: formatCurrency(pricing.deliveryCharge),
    baseDeliveryCharge: formatCurrency(pricing.baseDeliveryCharge), deliveryDiscount: formatCurrency(pricing.deliveryDiscount),
    productDiscount: formatCurrency(pricing.productDiscount), discount: formatCurrency(pricing.discount),
    tax: formatCurrency(pricing.tax), codCharge: formatCurrency(pricing.codCharge), 
    total: formatCurrency(pricing.total), savings: formatCurrency(totalSavings),
  }), [pricing, totalSavings, formatCurrency]);
  const refreshDeliveryCharge = () => {
    if (storeUid) dispatch(getDeliveryCharge(storeUid));
  };
  return {
    pricing, pricingSummary, totalSavings, potentialSavings: totalSavings, 
    discountBreakdown, deliveryChargeInfo, deliveryCharge, deliveryChargeLoading, 
    isFreeDeliveryEligible, formatCurrency, refreshDeliveryCharge,
  };
};

import { useMemo } from 'react';
import { UserCoupon } from '../../types/api';
import { useCurrencyFormatter } from '../../utils/currencyFormatter';

interface usePricingSummaryProps {
  subtotal: number;
  deliveryCharge: number;
  appliedCoupon: UserCoupon | null;
}

interface UsePricingSummaryReturn {
  formatCurrency: (amount: number) => string;
  freeShippingInfo: {
    freeShippingThreshold: number;
    amountForFreeShipping: number;
    isFreeShipping: boolean;
    isFreeShippingCoupon: boolean;
    progressPercentage: number;
    showProgressBar: boolean;
    showBadge: boolean;
  };
}

export const usePricingSummary = ({ subtotal, deliveryCharge, appliedCoupon }: usePricingSummaryProps): UsePricingSummaryReturn => {
  const { formatCurrency } = useCurrencyFormatter();
  const freeShippingInfo = useMemo(() => {
    const threshold = 500;
    const amountNeeded = Math.max(0, threshold - subtotal);
    const isFree = deliveryCharge === 0 || subtotal >= threshold;
    const progress = Math.min((subtotal / threshold) * 100, 100);
    return {
      freeShippingThreshold: threshold, amountForFreeShipping: amountNeeded, isFreeShipping: isFree,
      isFreeShippingCoupon: appliedCoupon?.coupon_type === 'free-shipping' && deliveryCharge === 0,
      progressPercentage: progress, showProgressBar: !isFree && amountNeeded > 0,
      showBadge: isFree && deliveryCharge === 0,
    };
  }, [subtotal, deliveryCharge, appliedCoupon]);
  return { formatCurrency, freeShippingInfo };
};

