import { useCallback } from 'react';
import { DeliverySlot } from '../../types/api';

interface CapacityStatus {
  text: string;
  color: string;
}

interface UseDeliverySlotCapacityReturn {
  getCapacityPercentage: (slot: DeliverySlot) => number;
  getCapacityStatus: (slot: DeliverySlot) => CapacityStatus;
  isSlotFull: (slot: DeliverySlot) => boolean;
  isSlotPopular: (slot: DeliverySlot) => boolean;
}

export const useDeliverySlotCapacity = (): UseDeliverySlotCapacityReturn => {
  const getCapacityPercentage = useCallback((slot: DeliverySlot): number => {
    if (!slot.max_orders_per_slot || slot.order_count === undefined) return 0;
    return (slot.order_count / slot.max_orders_per_slot) * 100;
  }, []);

  const getCapacityStatus = useCallback((slot: DeliverySlot): CapacityStatus => {
    const pct = getCapacityPercentage(slot);
    if (pct >= 100) return { text: 'Full', color: 'text-red-600 dark:text-red-400' };
    if (pct >= 75) return { text: 'Almost Full', color: 'text-orange-600 dark:text-orange-400' };
    if (pct >= 50) return { text: 'Filling Fast', color: 'text-yellow-600 dark:text-yellow-400' };
    return { text: 'Available', color: 'text-green-600 dark:text-green-400' };
  }, [getCapacityPercentage]);

  const isSlotFull = useCallback((slot: DeliverySlot): boolean => 
    !!(slot.max_orders_per_slot && slot.order_count !== undefined && slot.order_count >= slot.max_orders_per_slot)
  , []);

  const isSlotPopular = useCallback((slot: DeliverySlot): boolean => {
    const pct = getCapacityPercentage(slot);
    return pct >= 50 && pct < 100;
  }, [getCapacityPercentage]);

  return { getCapacityPercentage, getCapacityStatus, isSlotFull, isSlotPopular };
};

import { useMemo } from 'react';
import { DeliverySlot } from '../../types/api';

interface UseDeliverySlotsReturn {
  availableDates: string[];
  slotsForDate: DeliverySlot[];
  hasSlots: boolean;
  hasSlotsForDate: boolean;
}

export const useDeliverySlots = (deliverySlots: DeliverySlot[], selectedDate: string | null): UseDeliverySlotsReturn => {
  const availableDates = useMemo(() => 
    [...new Set(deliverySlots.map(s => s.delivery_date))].filter(Boolean).sort() as string[]
  , [deliverySlots]);

  const slotsForDate = useMemo(() => 
    selectedDate ? deliverySlots.filter(s => s.delivery_date === selectedDate) : []
  , [deliverySlots, selectedDate]);

  return {
    availableDates,
    slotsForDate,
    hasSlots: deliverySlots.length > 0,
    hasSlotsForDate: slotsForDate.length > 0,
  };
};

import { useState, useCallback } from 'react';
import { orderApi } from '../../services/orderApi';
import { toast } from 'react-hot-toast';

interface UseOrderCancelReturn {
  cancelOrder: (orderUid: string, reason?: string) => Promise<boolean>;
  loading: boolean;
}

export const useOrderCancel = (): UseOrderCancelReturn => {
  const [loading, setLoading] = useState(false);

  const cancelOrder = useCallback(async (orderUid: string, reason?: string): Promise<boolean> => {
    setLoading(true);
    try {
      const res = await orderApi.cancelOrder(orderUid, reason);
      const success = res.success;
      toast[success ? 'success' : 'error'](res.message || (success ? 'Order cancelled successfully' : 'Failed to cancel order'));
      return success;
    } catch (err) {
      const errorMessage = err instanceof Error ? err.message : 'An error occurred while cancelling the order';
      toast.error(errorMessage);
      return false;
    } finally {
      setLoading(false);
    }
  }, []);

  return { cancelOrder, loading };
};

import { useState, useEffect, useCallback } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { fetchOrderDetails, fetchOrderTimeline, fetchOrderUserDetails, fetchOrderSummary } from '../../store/slices/orderSlice';
import { OrderProduct, OrderTimelineItem, OrderUserDetails, OrderSummary } from '../../types/api';

interface UseOrderDetailsReturn {
  orderDetails: OrderProduct[];
  timeline: OrderTimelineItem[];
  userDetails: OrderUserDetails | null;
  orderSummary: OrderSummary | null;
  loading: boolean;
  error: string | null;
  isRefreshing: boolean;
  refreshOrderData: () => Promise<void>;
}

export const useOrderDetails = (orderUid: string | undefined): UseOrderDetailsReturn => {
  const dispatch = useAppDispatch();
  const { orderDetails, timeline, userDetails, orderSummary, main } = useAppSelector(state => state.order);
  const [isRefreshing, setIsRefreshing] = useState(false);

  const fetchAllOrderData = useCallback(async () => {
    if (!orderUid) return;
    try {
      await Promise.all([
        dispatch(fetchOrderDetails(orderUid)),
        dispatch(fetchOrderTimeline(orderUid)),
        dispatch(fetchOrderUserDetails(orderUid)),
        dispatch(fetchOrderSummary(orderUid))
      ]);
    } catch (error) {
      console.error('Failed to fetch order data:', error);
    }
  }, [orderUid, dispatch]);

  const refreshOrderData = useCallback(async () => {
    setIsRefreshing(true);
    await fetchAllOrderData();
    setIsRefreshing(false);
  }, [fetchAllOrderData]);

  useEffect(() => {
    if (orderUid) fetchAllOrderData();
  }, [orderUid, fetchAllOrderData]);

  return {
    orderDetails: orderDetails as OrderProduct[],
    timeline: timeline as OrderTimelineItem[],
    userDetails: userDetails as OrderUserDetails | null,
    orderSummary: orderSummary as OrderSummary | null,
    loading: main.loading,
    error: main.error,
    isRefreshing,
    refreshOrderData,
  };
};

