  useMemo(() => ({
    showRefreshButton: true,
    showCancelButton: canCancel,
    isRefreshDisabled: isRefreshing,
    refreshButtonState: isRefreshing ? 'loading' as const : 'idle' as const,
  }), [isRefreshing, canCancel]);

