  const fetchParams = useMemo(() => ({ 
    limit: FEATURED_PRODUCTS_LIMIT, 
    offset: INITIAL_OFFSET, 
    sort_by: DEFAULT_SORT_BY 
  }), []);

  return useProductData({
    selector: (state) => ({
