};

import { useAppSelector, useAppDispatch } from '../redux';
import { useEffect, useRef } from 'react';
import { Product } from '../../types/api';
import { RootState } from '../../store';
import { AsyncThunk } from '@reduxjs/toolkit';

interface UseProductDataParams {
  selector: (state: RootState) => { products: Product[]; loading: boolean; error: string | null };
  action: AsyncThunk<Product[], any, any>;
  fetchParams: Record<string, string | number | boolean>;
}

interface UseProductDataReturn {
  products: Product[];
  loading: boolean;
  error: string | null;
  refetch: () => void;
}

export const useProductData = ({ selector, action, fetchParams }: UseProductDataParams): UseProductDataReturn => {
  const dispatch = useAppDispatch();
  const { products, loading, error } = useAppSelector(selector);
  const hasInitialized = useRef(false);

  useEffect(() => {
    if (!hasInitialized.current && !loading && products.length === 0) {
      hasInitialized.current = true;
      dispatch(action(fetchParams));
    }
  }, [dispatch, loading, action, fetchParams]);

  return {
    products,
    loading,
    error,
    refetch: () => {
      hasInitialized.current = false;
      dispatch(action(fetchParams));
    }
  };
};

import { useEffect, useRef, useCallback } from 'react';
import { useParams } from 'react-router-dom';
import { useAppDispatch } from '../redux/useAppDispatch';
import { useAppSelector } from '../redux/useAppSelector';
import { getProductDetails, getProductReviews, getRelatedProducts } from '../../store/slices/productSlice';
import { Product, ProductRating } from '../../types/api';

interface UseProductDetailsReturn {
  product: Product | null;
  reviews: ProductRating[];
  relatedProducts: Product[];
  loading: boolean;
  error: string | null;
  averageRating: number;
  totalReviews: number;
  refetch: () => void;
}

export const useProductDetails = (): UseProductDetailsReturn => {
  const { productId } = useParams<{ productId: string }>();
  const dispatch = useAppDispatch();
  const lastProductId = useRef<string | null>(null);
  
  const {
    currentProduct,
    productReviews,
    relatedProducts,
    main,
    reviews,
    related
  } = useAppSelector((state) => state.product);

  const fetchProductDetails = useCallback(async () => {
    if (!productId) return;

    try {
      await dispatch(getProductDetails({ productUid: productId }));
      await Promise.all([
        dispatch(getProductReviews({ product_uid: productId })),
        dispatch(getRelatedProducts({ product_uid: productId }))
      ]);
    } catch (err) {
      console.error('Failed to fetch product data:', err);
    }
  }, [dispatch, productId]);

  useEffect(() => {
    // Only fetch if productId has changed
    if (productId && productId !== lastProductId.current) {
      lastProductId.current = productId;
      fetchProductDetails();
    }
  }, [productId, fetchProductDetails]);

  const averageRating = productReviews.length > 0 
    ? productReviews.reduce((sum, review) => sum + review.ratings, 0) / productReviews.length 
    : 0;

  return {
    product: currentProduct,
    reviews: productReviews,
    relatedProducts,
    loading: main.loading || reviews.loading || related.loading,
    error: main.error || reviews.error || related.error,
    averageRating,
    totalReviews: productReviews.length,
    refetch: fetchProductDetails
  };
};

import { useCallback, useEffect, useState, useRef, useMemo } from 'react';
import { useAppDispatch } from '../redux/useAppDispatch';
import { useAppSelector } from '../redux/useAppSelector';
import { 
  searchProducts, 
  loadMoreProducts, 
  getAllCategories,
  setSearchQuery,
  setSortBy,
  setAvailability,
  setSelectedCategory,
  setSelectedSubCategory,
  setCurrentPage,
  resetFilters,
  clearProducts
} from '../../store/slices/productSlice';
import { useDebounce } from '../utils/useDebounce';
import { DEFAULT_LIMIT } from '../../utils/constants';
import { Product } from '../../types/api';

export const useProductList = () => {
  const dispatch = useAppDispatch();

  // Memoize selector to prevent unnecessary re-renders
  const productState = useAppSelector((state) => state.product);
  const {
    products,
    categories,
    main,
    infiniteScroll,
    searchQuery,
    sortBy,
    availability,
    selectedCategory,
    selectedSubCategory,
    currentPage,
    hasMore,
    totalProducts
  } = productState;

  // Use searchQuery directly from Redux instead of duplicating in local state
  const debouncedSearchQuery = useDebounce(searchQuery, 300);
  const [viewMode, setViewMode] = useState<'pagination' | 'infinite'>('pagination');
  const initialLoadTriggered = useRef(false);
  const isSearching = useRef(false);
  const previousDebouncedQuery = useRef(searchQuery);

  // Price range and rating filter states
  const [priceRange, setPriceRange] = useState({ min: 0, max: 10000 });
  const [selectedRating, setSelectedRating] = useState(0);

  const totalPages = useMemo(() => Math.ceil(totalProducts / DEFAULT_LIMIT), [totalProducts]);

  // Memoize rating calculation to avoid recalculating on every render
  const calculateAverageRating = useCallback((product: Product): number => {
    if (!product.product_ratings?.length) return 0;
    const sum = product.product_ratings.reduce((acc: number, rating) => acc + rating.ratings, 0);
    return sum / product.product_ratings.length;
  }, []);

  // Apply price and rating filters - only when filters change
  const filteredProducts = useMemo(() => {
    // Skip filtering if no filters are active
    if (priceRange.min === 0 && priceRange.max === 10000 && selectedRating === 0) {
      return products;
    }

    return products.filter((product) => {
      const price = parseFloat(product.price);
      const isPriceInRange = price >= priceRange.min && (priceRange.max === 0 || price <= priceRange.max);

      if (!isPriceInRange) return false;

      if (selectedRating > 0) {
        const avgRating = calculateAverageRating(product);
        return avgRating > 0 && avgRating >= selectedRating;
      }

      return true;
    });
  }, [products, priceRange.min, priceRange.max, selectedRating, calculateAverageRating]);

  // Memoize search params object creation
  const getSearchParams = useCallback((overrides = {}) => ({
    searchQuery,
    sortBy,
    availability,
    category_uid: selectedCategory,
    sub_category_uid: selectedSubCategory,
    ...overrides
  }), [searchQuery, sortBy, availability, selectedCategory, selectedSubCategory]);

  const performSearch = useCallback((params = {}) => {
    if (isSearching.current) return;
    isSearching.current = true;
    dispatch(clearProducts());
    dispatch(searchProducts({ ...getSearchParams(params), reset: true })).finally(() => {
      isSearching.current = false;
    });
  }, [dispatch, getSearchParams]);

  // Load categories once on mount
  useEffect(() => {
    dispatch(getAllCategories());
  }, [dispatch]);

  // Initial product load - only once
  useEffect(() => {
    if (!initialLoadTriggered.current && products.length === 0 && !main.loading) {
      initialLoadTriggered.current = true;
      dispatch(searchProducts({ reset: true }));
    }
  }, [dispatch, products.length, main.loading]);

  // Handle debounced search - trigger search when debounced value changes
  useEffect(() => {
    if (debouncedSearchQuery !== previousDebouncedQuery.current) {
      previousDebouncedQuery.current = debouncedSearchQuery;
      dispatch(clearProducts());
      dispatch(searchProducts({ searchQuery: debouncedSearchQuery, reset: true }));
    }
  }, [debouncedSearchQuery, dispatch]);

  // Optimized handlers - combined Redux action + search into single function
  const handleSortChange = useCallback((newSortBy: string) => {
    if (newSortBy === sortBy) return;
    dispatch(setSortBy(newSortBy));
    dispatch(clearProducts());
    dispatch(searchProducts({ sortBy: newSortBy, reset: true }));
  }, [dispatch, sortBy]);

  const handleAvailabilityChange = useCallback((newAvailability: string) => {
    if (newAvailability === availability) return;
    dispatch(setAvailability(newAvailability));
    dispatch(clearProducts());
    dispatch(searchProducts({ availability: newAvailability, reset: true }));
  }, [dispatch, availability]);

  const handleCategoryChange = useCallback((categoryUid: string) => {
    if (categoryUid === selectedCategory) return;
    dispatch(setSelectedCategory(categoryUid));
    dispatch(setSelectedSubCategory(''));
    dispatch(clearProducts());
    dispatch(searchProducts({ category_uid: categoryUid, sub_category_uid: '', reset: true }));
  }, [dispatch, selectedCategory]);

  const handleSubCategoryChange = useCallback((subCategoryUid: string) => {
    if (subCategoryUid === selectedSubCategory) return;
    dispatch(setSelectedSubCategory(subCategoryUid));
    dispatch(clearProducts());
    dispatch(searchProducts({ sub_category_uid: subCategoryUid, reset: true }));
  }, [dispatch, selectedSubCategory]);

  const handlePageChange = useCallback((page: number) => {
    if (page === currentPage) return;
    dispatch(setCurrentPage(page));
    dispatch(searchProducts({ 
      searchQuery,
      sortBy,
      availability,
      category_uid: selectedCategory,
      sub_category_uid: selectedSubCategory,
      offset: page, 
      reset: false 
    }));
  }, [dispatch, currentPage, searchQuery, sortBy, availability, selectedCategory, selectedSubCategory]);

  const handleLoadMore = useCallback(() => {
    if (hasMore && !infiniteScroll.loading && !main.loading) {
      dispatch(loadMoreProducts());
    }
  }, [dispatch, hasMore, infiniteScroll.loading, main.loading]);

  // Simplified handlers without unnecessary callbacks
  const handlePriceRangeChange = useCallback((range: { min: number; max: number }) => {
    setPriceRange(range);
  }, []);

  const handleRatingChange = useCallback((rating: number) => {
    setSelectedRating(rating);
  }, []);

  const handleResetFilters = useCallback(() => {
    dispatch(resetFilters());
    setPriceRange({ min: 0, max: 10000 });
    setSelectedRating(0);
    // No need to call searchProducts - resetFilters already clears products
  }, [dispatch]);

  const handleViewModeChange = useCallback((mode: 'pagination' | 'infinite') => {
    setViewMode(mode);
  }, []);

  const refetch = useCallback(() => {
    initialLoadTriggered.current = false;
    dispatch(clearProducts());
    dispatch(searchProducts({ reset: true }));
  }, [dispatch]);

  // Handler for search input - dispatch directly to Redux
  const handleSearchChange = useCallback((value: string) => {
    dispatch(setSearchQuery(value));
  }, [dispatch]);

  return {
    products,
    filteredProducts,
    categories,
    loading: main.loading,
    error: main.error,
    searchQuery, // Return searchQuery directly from Redux
    sortBy,
    availability,
    selectedCategory,
    selectedSubCategory,
    currentPage,
    hasMore,
    infiniteScrollLoading: infiniteScroll.loading,
    totalProducts,
    totalPages,
    viewMode,
    priceRange,
    selectedRating,
    // Handlers
    handleSearchChange,
    handleSortChange,
    handleAvailabilityChange,
    handleCategoryChange,
    handleSubCategoryChange,
    handlePageChange,
    handleLoadMore,
    handlePriceRangeChange,
    handleRatingChange,
    handleResetFilters,
    handleViewModeChange,
    refetch,
    // Utilities
    calculateAverageRating,
  };
};

import { useMemo } from 'react';
import { useAppSelector } from '../redux/useAppSelector';
import { Category, Product, ProductRating } from '../../types/api';
import { CategoryDisplayData, formatCategoryForDisplay, formatProductForDisplay, ProductDisplayData } from '../../utils/productUtils';

export const useProductUtils = () => {
  const { defaultTenant } = useAppSelector((state) => state.tenant);
  
  return useMemo(() => ({
    formatProductForDisplay: (product: Product, ratings: ProductRating[] = []) => 
      formatProductForDisplay(product, defaultTenant, ratings),
  }), [defaultTenant]);
};

export const useProductDisplayData = (product: Product): ProductDisplayData => {
  const { productReviews } = useAppSelector((state) => state.product);
  const { defaultTenant } = useAppSelector((state) => state.tenant);
  
  const productRatings = useMemo(() => 
    productReviews.filter(review => review.product_uid === product.product_uid),
    [productReviews, product.product_uid]
  );
  
  return useMemo(() => 
    formatProductForDisplay(product, defaultTenant, productRatings),
    [product, defaultTenant, productRatings]
  );
};

export const useCategoryDisplayData = (category: Category): CategoryDisplayData => {
  const displayData = useMemo(() => {
    return formatCategoryForDisplay(category);
  }, [category]);

  return displayData;
};

