import { useState, useEffect } from 'react';

export const useDebounce = <T,>(value: T, delay: number): T => {
  const [debouncedValue, setDebouncedValue] = useState<T>(value);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedValue(value), delay);
    return () => clearTimeout(handler);
  }, [value, delay]);

  return debouncedValue;
};

import { useEffect, useRef, useState } from 'react';

interface UseIntersectionObserverOptions {
  threshold?: number;
  rootMargin?: string;
  triggerOnce?: boolean;
}

interface UseIntersectionObserverReturn<T extends HTMLElement = HTMLElement> {
  elementRef: React.RefObject<T | null>;
  isIntersecting: boolean;
}

export const useIntersectionObserver = <T extends HTMLElement = HTMLElement>(
  options: UseIntersectionObserverOptions = {}
): UseIntersectionObserverReturn<T> => {
  const { threshold = 0.1, rootMargin = '0px', triggerOnce = true } = options;
  const [isIntersecting, setIsIntersecting] = useState(false);
  const [hasTriggered, setHasTriggered] = useState(false);
  const elementRef = useRef<T>(null);

  useEffect(() => {
    const element = elementRef.current;
    if (!element) return;

    const observer = new IntersectionObserver(
      ([entry]) => {
        const isVisible = entry.isIntersecting;
        const shouldUpdate = isVisible && (!triggerOnce || !hasTriggered);

        if (shouldUpdate) {
          setIsIntersecting(true);
          if (triggerOnce) setHasTriggered(true);
        } else if (!triggerOnce) {
          setIsIntersecting(isVisible);
        }
      },
      { threshold, rootMargin }
    );

    observer.observe(element);
    return () => observer.unobserve(element);
  }, [threshold, rootMargin, triggerOnce, hasTriggered]);

  return { elementRef, isIntersecting };
};

import { useState } from 'react';

type UseLocalStorageReturn<T> = readonly [T, (value: T | ((val: T) => T)) => void];

export const useLocalStorage = <T,>(key: string, initialValue: T): UseLocalStorageReturn<T> => {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? JSON.parse(item) : initialValue;
    } catch {
      return initialValue;
    }
  });

  const setValue = (value: T | ((val: T) => T)) => {
    try {
      const valueToStore = value instanceof Function ? value(storedValue) : value;
      setStoredValue(valueToStore);
      window.localStorage.setItem(key, JSON.stringify(valueToStore));
    } catch {
      // Silently fail for localStorage errors
    }
  };

  return [storedValue, setValue] as const;
};

import { useState, useCallback } from 'react';

interface UseModalReturn {
  isOpen: boolean;
  openModal: () => void;
  closeModal: () => void;
  toggleModal: () => void;
  message: string;
  setMessage: React.Dispatch<React.SetStateAction<string>>;
}

export const useModal = (defaultMessage?: string): UseModalReturn => {
  const [isOpen, setIsOpen] = useState(false);
  const [message, setMessage] = useState(defaultMessage || '');

  const openModal = useCallback(() => setIsOpen(true), []);
  const closeModal = useCallback(() => setIsOpen(false), []);
  const toggleModal = useCallback(() => setIsOpen(prev => !prev), []);

  return { isOpen, openModal, closeModal, toggleModal, message, setMessage };
};

import { useEffect, useRef } from 'react';

declare global {
  interface Window {
    gtag?: (...args: Array<string | number | Record<string, string | number>>) => void;
  }
}

interface UsePerformanceMonitorReturn {
  markRenderStart: () => void;
  markRenderEnd: () => void;
}

export const usePerformanceMonitor = (componentName: string): UsePerformanceMonitorReturn => {
  const startTime = useRef<number>(Date.now());
  const renderStartTime = useRef<number>(Date.now());

  useEffect(() => {
    const loadTime = Date.now() - startTime.current;

    if (process.env.NODE_ENV === 'development') {
      console.log(`Performance [${componentName}]: ${loadTime}ms`);
    } else if (window.gtag) {
      window.gtag('event', 'timing_complete', { name: componentName, value: loadTime });
    }
  }, [componentName]);

  const markRenderStart = () => { renderStartTime.current = Date.now(); };
  const markRenderEnd = () => {
    const renderTime = Date.now() - renderStartTime.current;
    if (process.env.NODE_ENV === 'development') {
      console.log(`Render Time [${componentName}]: ${renderTime}ms`);
    }
  };

  return { markRenderStart, markRenderEnd };
};

export const useWebVitals = (): void => {
  useEffect(() => {
    if (typeof window !== 'undefined') {
      import('web-vitals').then(({ onCLS, onFCP, onLCP, onTTFB }) => {
        [onCLS, onFCP, onLCP, onTTFB].forEach(metric => metric(console.log));
      });
    }
  }, []);
};

import { useCallback, useRef } from 'react';

interface RetryOptions {
  maxRetries?: number;
  baseDelay?: number;
  maxDelay?: number;
  backoffMultiplier?: number;
}

interface UseSmartRetryReturn<T = unknown> {
  executeWithRetry: (
    key: string,
    operation: () => Promise<T>,
    onRetry?: (attempt: number, error: Error) => void
  ) => Promise<T>;
  resetRetryCount: (key: string) => void;
}

export const useSmartRetry = <T = unknown,>(options: RetryOptions = {}): UseSmartRetryReturn<T> => {
  const { maxRetries = 3, baseDelay = 1000, maxDelay = 10000, backoffMultiplier = 2 } = options;
  const retryCountRef = useRef<Map<string, number>>(new Map());

  const executeWithRetry = useCallback(async (
    key: string,
    operation: () => Promise<T>,
    onRetry?: (attempt: number, error: Error) => void
  ): Promise<T> => {
    const retryCount = retryCountRef.current.get(key) || 0;

    try {
      const result = await operation();
      retryCountRef.current.delete(key);
      return result;
    } catch (error) {
      if (retryCount < maxRetries) {
        const delay = Math.min(baseDelay * Math.pow(backoffMultiplier, retryCount), maxDelay);
        retryCountRef.current.set(key, retryCount + 1);
        onRetry?.(retryCount + 1, error as Error);
        await new Promise(resolve => setTimeout(resolve, delay));
        return executeWithRetry(key, operation, onRetry);
      }
      retryCountRef.current.delete(key);
      throw error;
    }
  }, [maxRetries, baseDelay, maxDelay, backoffMultiplier]);

  return { executeWithRetry, resetRetryCount: (key: string) => retryCountRef.current.delete(key) };
};

