import { useCallback, useMemo } from 'react';
import { useAppDispatch, useAppSelector } from '../redux';
import { addToWishlist, removeFromWishlist } from '../../store/slices/wishlistSlice';
import { Product } from '../../types/api';
import { useToast } from '../ui/useToast';

interface UseWishlistActionsReturn {
  wishlistItems: Product[];
  wishlistProductUids: string[];
  isInWishlist: (uid: string) => boolean;
  handleAddToWishlist: (product: Product) => Promise<boolean>;
  handleRemoveFromWishlist: (uid: string) => Promise<boolean>;
  handleToggleWishlist: (product: Product) => Promise<boolean>;
}

export const useWishlistActions = (): UseWishlistActionsReturn => {
  const dispatch = useAppDispatch();
  const { success, error } = useToast();
  const { wishlistItems } = useAppSelector((state) => state.wishlist);
  const wishlistProductUids = useMemo(() => 
    new Set(wishlistItems.map(item => item.product_uid)), [wishlistItems]);
  const isInWishlist = useCallback((uid: string) => 
    wishlistProductUids.has(uid), [wishlistProductUids]);
  const handleAddToWishlist = useCallback(async (product: Product) => {
    try {
      await dispatch(addToWishlist(product)).unwrap();
      success('Added to wishlist!');
      return true;
    } catch {
      error('Failed to add to wishlist');
      return false;
    }
  }, [dispatch, success, error]);
  const handleRemoveFromWishlist = useCallback(async (uid: string) => {
    try {
      await dispatch(removeFromWishlist(uid)).unwrap();
      success('Removed from wishlist');
      return true;
    } catch {
      error('Failed to remove from wishlist');
      return false;
    }
  }, [dispatch, success, error]);
  const handleToggleWishlist = useCallback(async (product: Product) => 
    wishlistProductUids.has(product.product_uid)
      ? handleRemoveFromWishlist(product.product_uid)
      : handleAddToWishlist(product),
    [wishlistProductUids, handleAddToWishlist, handleRemoveFromWishlist]
  );
  return {
    wishlistItems, wishlistProductUids: Array.from(wishlistProductUids), isInWishlist,
    handleAddToWishlist, handleRemoveFromWishlist, handleToggleWishlist,
  };
};

import { useCallback } from 'react';
import { useCartActions } from '../cart/useCartActions';
import { useWishlistActions } from './useWishlistActions';
import { useToast } from '../ui/useToast';
import type { Product } from '../../types/api';
import type { ProductDisplayData } from '../../utils/productUtils';

interface UseWishlistBulkActionsParams {
  selectedItems: Set<string>;
  products: Product[];
  displayDataMap: Map<string, ProductDisplayData>;
  clearSelection: () => void;
}

interface UseWishlistBulkActionsReturn {
  handleRemoveSelected: () => Promise<void>;
  handleMoveSelectedToCart: () => Promise<void>;
}

export const useWishlistBulkActions = ({
  selectedItems,
  products,
  displayDataMap,
  clearSelection,
}: UseWishlistBulkActionsParams): UseWishlistBulkActionsReturn => {
  const { handleAddToCart } = useCartActions();
  const { handleRemoveFromWishlist } = useWishlistActions();
  const { success, error: errorToast, warning } = useToast();

  const handleRemoveSelected = useCallback(async () => {
    if (selectedItems.size === 0) {
      warning('No items selected');
      return;
    }

    // Show confirmation dialog
    const confirmed = window.confirm(
      `Are you sure you want to remove ${selectedItems.size} item${
        selectedItems.size > 1 ? 's' : ''
      } from your wishlist?`
    );

    if (!confirmed) return;

    try {
      const removePromises = Array.from(selectedItems).map((productUid) =>
        handleRemoveFromWishlist(productUid)
      );

      await Promise.all(removePromises);

      success(
        `${selectedItems.size} item${
          selectedItems.size > 1 ? 's' : ''
        } removed from wishlist`
      );
      clearSelection();
    } catch (err) {
      console.error('Failed to remove selected items:', err);
      errorToast('Failed to remove some items. Please try again.');
    }
  }, [
    selectedItems,
    handleRemoveFromWishlist,
    clearSelection,
    success,
    errorToast,
    warning,
  ]);

  const handleMoveSelectedToCart = useCallback(async () => {
    if (selectedItems.size === 0) {
      warning('No items selected');
      return;
    }

    try {
      let movedCount = 0;
      let skippedCount = 0;

      for (const productUid of selectedItems) {
        const product = products.find((p) => p.product_uid === productUid);
        const displayData = displayDataMap.get(productUid);

        if (!product || !displayData) continue;

        // Skip out-of-stock items
        if (!displayData.isAvailable) {
          skippedCount++;
          continue;
        }

        // Add to cart with quantity 1
        const cartSuccess = await handleAddToCart(product, displayData, 1);
        if (cartSuccess) {
          // Remove from wishlist after successful cart addition
          await handleRemoveFromWishlist(productUid);
          movedCount++;
        }
      }

      if (movedCount > 0) {
        success(
          `${movedCount} item${movedCount > 1 ? 's' : ''} moved to cart`
        );
      }

      if (skippedCount > 0) {
        warning(
          `${skippedCount} out-of-stock item${
            skippedCount > 1 ? 's' : ''
          } skipped`
        );
      }

      clearSelection();
    } catch (err) {
      console.error('Failed to move selected items to cart:', err);
      errorToast('Failed to move some items to cart. Please try again.');
    }
  }, [
    selectedItems,
    products,
    displayDataMap,
    handleAddToCart,
    handleRemoveFromWishlist,
    clearSelection,
    success,
    errorToast,
    warning,
  ]);

  return {
    handleRemoveSelected,
    handleMoveSelectedToCart,
  };
};

import { useMemo } from 'react';
import { useProductUtils } from '../product/useProductUtils';
import type { Product } from '../../types/api';
import type { ProductDisplayData } from '../../utils/productUtils';

interface UseWishlistDisplayDataParams {
  products: Product[];
}

interface UseWishlistDisplayDataReturn {
  displayDataMap: Map<string, ProductDisplayData>;
}

export const useWishlistDisplayData = ({
  products,
}: UseWishlistDisplayDataParams): UseWishlistDisplayDataReturn => {
  const { formatProductForDisplay } = useProductUtils();

  const displayDataMap = useMemo(() => {
    const map = new Map<string, ProductDisplayData>();

    products.forEach((product) => {
      const displayData = formatProductForDisplay(product);
      map.set(product.product_uid, displayData);
    });

    return map;
  }, [products, formatProductForDisplay]);

  return { displayDataMap };
};

import { useState, useMemo, useCallback } from 'react';
import type { Product } from '../../types/api';
import type { ProductDisplayData } from '../../utils/productUtils';

export type SortOption = 'recent' | 'price-low' | 'price-high' | 'name';

interface UseWishlistFiltersParams {
  products: Product[];
  displayDataMap: Map<string, ProductDisplayData>;
}

interface UseWishlistFiltersReturn {
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  sortBy: SortOption;
  setSortBy: (sort: SortOption) => void;
  sortedProducts: Product[];
}

export const useWishlistFilters = ({
  products,
  displayDataMap,
}: UseWishlistFiltersParams): UseWishlistFiltersReturn => {
  const [searchQuery, setSearchQuery] = useState('');
  const [sortBy, setSortBy] = useState<SortOption>('recent');

  // Filter by search query
  const filteredProducts = useMemo(() => {
    if (!searchQuery.trim()) return products;

    const query = searchQuery.toLowerCase();
    return products.filter((product) => {
      const displayData = displayDataMap.get(product.product_uid);
      if (!displayData) return false;

      return (
        displayData.displayName.toLowerCase().includes(query) ||
        product.product_uid.toLowerCase().includes(query) ||
        (displayData.brand && displayData.brand.toLowerCase().includes(query))
      );
    });
  }, [products, searchQuery, displayDataMap]);

  // Sort filtered products
  const sortedProducts = useMemo(() => {
    const sorted = [...filteredProducts];

    switch (sortBy) {
      case 'recent':
        // Most recent first - keep original order (wishlist order)
        return sorted;

      case 'price-low':
        return sorted.sort((a, b) => {
          const priceA = displayDataMap.get(a.product_uid)?.discountedPrice || 0;
          const priceB = displayDataMap.get(b.product_uid)?.discountedPrice || 0;
          return priceA - priceB;
        });

      case 'price-high':
        return sorted.sort((a, b) => {
          const priceA = displayDataMap.get(a.product_uid)?.discountedPrice || 0;
          const priceB = displayDataMap.get(b.product_uid)?.discountedPrice || 0;
          return priceB - priceA;
        });

      case 'name':
        return sorted.sort((a, b) => {
          const nameA = displayDataMap.get(a.product_uid)?.displayName || '';
          const nameB = displayDataMap.get(b.product_uid)?.displayName || '';
          return nameA.localeCompare(nameB);
        });

      default:
        return sorted;
    }
  }, [filteredProducts, sortBy, displayDataMap]);

  const handleSetSearchQuery = useCallback((query: string) => {
    setSearchQuery(query);
  }, []);

  const handleSetSortBy = useCallback((sort: SortOption) => {
    setSortBy(sort);
  }, []);

  return {
    searchQuery,
    setSearchQuery: handleSetSearchQuery,
    sortBy,
    setSortBy: handleSetSortBy,
    sortedProducts,
  };
};

import { useEffect } from 'react';
import { useAppSelector, useAppDispatch } from '../redux';
import { getUserWishlist } from '../../store/slices/wishlistSlice';
import { useWishlistDisplayData } from './useWishlistDisplayData';
import { useWishlistFilters, type SortOption } from './useWishlistFilters';
import { useWishlistSelection } from './useWishlistSelection';
import { useWishlistBulkActions } from './useWishlistBulkActions';
import type { Product } from '../../types/api';
import type { ProductDisplayData } from '../../utils/productUtils';

interface UseWishlistPageReturn {
  wishlistItems: Product[];
  loading: boolean;
  sortedProducts: Product[];
  displayDataMap: Map<string, ProductDisplayData>;
  searchQuery: string;
  setSearchQuery: (query: string) => void;
  sortBy: SortOption;
  setSortBy: (sort: SortOption) => void;
  selectedItems: Set<string>;
  selectedCount: number;
  handleToggleSelect: (productUid: string) => void;
  handleSelectAll: () => void;
  handleDeselectAll: () => void;
  handleRemoveSelected: () => Promise<void>;
  handleMoveSelectedToCart: () => Promise<void>;
}

/**
 * PRIMARY HOOK for Wishlist Page
 * Composes all wishlist functionality into a single hook
 * 
 * Usage:
 * ```tsx
 * const {
 *   wishlistItems,
 *   loading,
 *   sortedProducts,
 *   displayDataMap,
 *   searchQuery,
 *   setSearchQuery,
 *   sortBy,
 *   setSortBy,
 *   selectedItems,
 *   selectedCount,
 *   handleToggleSelect,
 *   handleSelectAll,
 *   handleDeselectAll,
 *   handleRemoveSelected,
 *   handleMoveSelectedToCart,
 * } = useWishlistPage();
 * ```
 */
export const useWishlistPage = (): UseWishlistPageReturn => {
  const dispatch = useAppDispatch();
  const wishlistItems = useAppSelector((state) => state.wishlist.wishlistItems);
  const loading = useAppSelector((state) => state.wishlist.loading);

  // Fetch wishlist on mount
  useEffect(() => {
    dispatch(getUserWishlist());
  }, [dispatch]);

  // Create display data map
  const { displayDataMap } = useWishlistDisplayData({
    products: wishlistItems,
  });

  // Handle search and sort
  const { searchQuery, setSearchQuery, sortBy, setSortBy, sortedProducts } =
    useWishlistFilters({
      products: wishlistItems,
      displayDataMap,
    });

  // Handle selection
  const {
    selectedItems,
    selectedCount,
    handleToggleSelect,
    handleSelectAll,
    handleDeselectAll,
    clearSelection,
  } = useWishlistSelection({
    products: sortedProducts, // Use sorted products for selection
  });

  // Handle bulk actions
  const { handleRemoveSelected, handleMoveSelectedToCart } =
    useWishlistBulkActions({
      selectedItems,
      products: wishlistItems,
      displayDataMap,
      clearSelection,
    });

  return {
    wishlistItems,
    loading,
    sortedProducts,
    displayDataMap,
    searchQuery,
    setSearchQuery,
    sortBy,
    setSortBy,
    selectedItems,
    selectedCount,
    handleToggleSelect,
    handleSelectAll,
    handleDeselectAll,
    handleRemoveSelected,
    handleMoveSelectedToCart,
  };
};

import { useState, useCallback, useMemo } from 'react';
import type { Product } from '../../types/api';

interface UseWishlistSelectionParams {
  products: Product[];
}

interface UseWishlistSelectionReturn {
  selectedItems: Set<string>;
  selectedCount: number;
  handleToggleSelect: (productUid: string) => void;
  handleSelectAll: () => void;
  handleDeselectAll: () => void;
  clearSelection: () => void;
}

export const useWishlistSelection = ({
  products,
}: UseWishlistSelectionParams): UseWishlistSelectionReturn => {
  const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set());

  const selectedCount = useMemo(() => selectedItems.size, [selectedItems]);

  const handleToggleSelect = useCallback((productUid: string) => {
    setSelectedItems((prev) => {
      const newSet = new Set(prev);
      if (newSet.has(productUid)) {
        newSet.delete(productUid);
      } else {
        newSet.add(productUid);
      }
      return newSet;
    });
  }, []);

  const handleSelectAll = useCallback(() => {
    const allIds = new Set(products.map((product) => product.product_uid));
    setSelectedItems(allIds);
  }, [products]);

  const handleDeselectAll = useCallback(() => {
    setSelectedItems(new Set());
  }, []);

  const clearSelection = useCallback(() => {
    setSelectedItems(new Set());
  }, []);

  return {
    selectedItems,
    selectedCount,
    handleToggleSelect,
    handleSelectAll,
    handleDeselectAll,
    clearSelection,
  };
};

