  background: linear-gradient(90deg, #f0f0f0 25%, #e0e0e0 50%, #f0f0f0 75%);
  background-size: 200px 100%;
  animation: shimmer 1.5s infinite;
}

/* Custom focus styles */
.focus-ring {
  outline: none;
  box-shadow: 0 0 0 3px rgba(191, 160, 84, 0.5);
}

/* Smooth scrolling */
html {
  scroll-behavior: smooth;
}

/* Ensure smooth scrolling on all browsers */
* {
  scroll-behavior: smooth;
}

/* Optimize for smooth scrolling performance */
html, body {
  overflow-x: hidden;
  scroll-behavior: smooth;
}

/* Custom selection styles */
::selection {
  background: rgba(191, 160, 84, 0.2);
  color: var(--color-text);
}

/* Modern scrollbar for the entire page */
::-webkit-scrollbar {
  width: 12px;
}

::-webkit-scrollbar-track {
  background: var(--color-background);
}

::-webkit-scrollbar-thumb {
  background: var(--gradient-primary);
  border-radius: 6px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--gradient-secondary);
}

/* Responsive text sizing */
@media (max-width: 640px) {
  .text-responsive {
    font-size: 0.875rem;
  }
}

@media (min-width: 641px) and (max-width: 1024px) {
  .text-responsive {
    font-size: 1rem;
  }
}

@media (min-width: 1025px) {
  .text-responsive {
    font-size: 1.125rem;
  }
}

/* HTML Content Styling for Product Descriptions */
.prose p {
  margin-bottom: 1rem;
}

.prose h1, .prose h2, .prose h3, .prose h4, .prose h5, .prose h6 {
  font-weight: 600;
  margin-top: 1.5rem;
  margin-bottom: 0.75rem;
  line-height: 1.4;
}

.prose h1 { font-size: 1.875rem; }
.prose h2 { font-size: 1.5rem; }
.prose h3 { font-size: 1.25rem; }
.prose h4 { font-size: 1.125rem; }

.prose ul, .prose ol {
  margin-top: 0.75rem;
  margin-bottom: 1rem;
  padding-left: 1.5rem;
}

.prose ul {
  list-style-type: disc;
}

.prose ol {
  list-style-type: decimal;
}

.prose li {
  margin-bottom: 0.375rem;
}

.prose a {
  color: #3b82f6;
  text-decoration: underline;
}

.prose a:hover {
  color: #2563eb;
}

.prose strong {
  font-weight: 600;
}

.prose em {
  font-style: italic;
}

.prose blockquote {
  border-left: 4px solid #e5e7eb;
  padding-left: 1rem;
  margin: 1rem 0;
  font-style: italic;
  color: #6b7280;
}

.prose code {
  background-color: #f3f4f6;
  padding: 0.125rem 0.25rem;
  border-radius: 0.25rem;
  font-size: 0.875em;
  font-family: monospace;
}

.prose pre {
  background-color: #1f2937;
  color: #f9fafb;
  padding: 1rem;
  border-radius: 0.5rem;
  overflow-x: auto;
  margin: 1rem 0;
}

.prose table {
  width: 100%;
  border-collapse: collapse;
  margin: 1rem 0;
}

.prose th, .prose td {
  border: 1px solid #e5e7eb;
  padding: 0.5rem;
  text-align: left;
}

.prose th {
  background-color: #f9fafb;
  font-weight: 600;
}

.prose img {
  max-width: 100%;
  height: auto;
  border-radius: 0.5rem;
  margin: 1rem 0;
}

.prose hr {
  border: 0;
  border-top: 1px solid #e5e7eb;
  margin: 1.5rem 0;
}

/* Dark mode prose styles */
.prose-invert p,
.prose-invert li,
.prose-invert td {
  color: #d1d5db;
}

.prose-invert h1, .prose-invert h2, .prose-invert h3, 
.prose-invert h4, .prose-invert h5, .prose-invert h6 {
  color: #f9fafb;
}

.prose-invert blockquote {
  border-left-color: #374151;
  color: #9ca3af;
}

.prose-invert code {
  background-color: #374151;
  color: #e5e7eb;
}

.prose-invert th {
  background-color: #374151;
  color: #f9fafb;
}

.prose-invert th, .prose-invert td {
  border-color: #4b5563;
}

.prose-invert hr {
  border-top-color: #4b5563;
}

