import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import { addressApi } from '../../services/addressApi';
import { Address } from '../../types/api';

interface AddressState {
  addresses: Address[];
  loading: boolean;
  error: string | null;
}

const initialState: AddressState = {
  addresses: [],
  loading: false,
  error: null,
};
export const fetchUserAddresses = createAsyncThunk(
  'address/fetchUserAddresses',
  async (_, { rejectWithValue }) => {
    try {
      const response = await addressApi.getUserAddresses();
      if (!response.success) return rejectWithValue(response.message || 'Failed to fetch addresses');
      return response.data || [];
    } catch (error: any) {
      return rejectWithValue(error.message || 'Network error occurred');
    }
  }
);

export const createAddress = createAsyncThunk(
  'address/createAddress',
  async (addressData: any, { rejectWithValue }) => {
    try {
      const response = await addressApi.createAddress(addressData);
      if (!response.success) return rejectWithValue(response.message || 'Failed to create address');
      return response.data;
    } catch (error: any) {
      return rejectWithValue(error.message || 'Network error occurred');
    }
  }
);

export const updateAddress = createAsyncThunk(
  'address/updateAddress',
  async ({ addressId, addressData }: any, { rejectWithValue, dispatch }) => {
    try {
      const response = await addressApi.updateAddress(addressId, addressData);
      if (!response.success) return rejectWithValue(response.message || 'Failed to update address');
      // Refetch addresses after successful update
      await dispatch(fetchUserAddresses());
      return { addressId, updatedAddress: response.data };
    } catch (error: any) {
      return rejectWithValue(error.message || 'Network error occurred');
    }
  }
);

export const deleteAddress = createAsyncThunk(
  'address/deleteAddress',
  async (addressId: string, { rejectWithValue, dispatch }) => {
    try {
      const response = await addressApi.deleteAddress(addressId);
      if (!response.success) return rejectWithValue(response.message || 'Failed to delete address');
      // Refetch addresses after successful deletion
      await dispatch(fetchUserAddresses());
      return addressId;
    } catch (error: any) {
      return rejectWithValue(error.message || 'Network error occurred');
    }
  }
);

export const setDefaultAddress = createAsyncThunk(
  'address/setDefaultAddress',
  async (addressId: string, { rejectWithValue, dispatch }) => {
    try {
      const response = await addressApi.setDefaultAddress(addressId);
      if (!response.success) return rejectWithValue(response.message || 'Failed to set default address');
      // Refetch addresses after successfully setting default
      await dispatch(fetchUserAddresses());
      return addressId;
    } catch (error: any) {
      return rejectWithValue(error.message || 'Failed to set default address');
    }
  }
);

// Helper function for loading states
const handleLoading = (state: any, loading: boolean, error: string | null = null) => {
  state.loading = loading;
  if (error !== null) state.error = error;
};

// Helper function for setting default address
const setDefaultAddressHelper = (state: any, addressId: string) => {
  state.addresses = state.addresses.map((addr: Address) => ({
    ...addr,
    is_default: addr.b2c_address_id === addressId
  }));
};

const addressSlice = createSlice({
  name: 'address',
  initialState,
  reducers: {
    clearError: (state) => {
      state.error = null;
    },
  },
  extraReducers: (builder) => {
    builder
      // Fetch User Addresses
      .addCase(fetchUserAddresses.pending, (state) => handleLoading(state, true))
      .addCase(fetchUserAddresses.fulfilled, (state, action: PayloadAction<Address[]>) => {
        handleLoading(state, false);
        state.addresses = action.payload;
      })
      .addCase(fetchUserAddresses.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Create Address
      .addCase(createAddress.pending, (state) => handleLoading(state, true))
      .addCase(createAddress.fulfilled, (state, action) => {
        handleLoading(state, false);
        if (action.payload) {
          state.addresses.push(action.payload);
          if (action.payload.is_default) {
            setDefaultAddressHelper(state, action.payload.b2c_address_id);
          }
        }
      })
      .addCase(createAddress.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Update Address
      .addCase(updateAddress.pending, (state) => handleLoading(state, true))
      .addCase(updateAddress.fulfilled, (state, action) => {
        handleLoading(state, false);
        const { addressId, updatedAddress } = action.payload;
        if (updatedAddress) {
          const index = state.addresses.findIndex(addr => addr.b2c_address_id === addressId);
          if (index !== -1) {
            state.addresses[index] = updatedAddress;
            if (updatedAddress.is_default) {
              setDefaultAddressHelper(state, addressId);
            }
          }
        }
      })
      .addCase(updateAddress.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Delete Address
      .addCase(deleteAddress.pending, (state) => handleLoading(state, true))
      .addCase(deleteAddress.fulfilled, (state, action) => {
        handleLoading(state, false);
        state.addresses = state.addresses.filter(addr => addr.b2c_address_id !== action.payload);
      })
      .addCase(deleteAddress.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Set Default Address
      .addCase(setDefaultAddress.pending, (state) => handleLoading(state, true))
      .addCase(setDefaultAddress.fulfilled, (state, action) => {
        handleLoading(state, false);
        setDefaultAddressHelper(state, action.payload);
      })
      .addCase(setDefaultAddress.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string));
  },
});

export const { clearError } = addressSlice.actions;
export default addressSlice.reducer;

import { createSlice, createAsyncThunk, PayloadAction } from '@reduxjs/toolkit';
import { authApi } from '../../services/authApi';
import { User, LoginResponse } from '../../types/api';
import Cookies from 'js-cookie';

interface AuthState {
  user: User | null;
  isAuthenticated: boolean;
  loading: boolean;
  error: string | null;
}

// Consolidated storage operations
const storageOps = {
  getUser: (): User | null => {
    try {
      const userData = localStorage.getItem('user');
      return userData ? JSON.parse(userData) : null;
    } catch (error) {
      console.warn('Failed to parse user data from localStorage:', error);
      return null;
    }
  },
  setUser: (user: User): void => {
    localStorage.setItem('user', JSON.stringify(user));
  },
  setTokens: (accessToken: string, refreshToken: string): void => {
    localStorage.setItem('accessToken', accessToken);
    localStorage.setItem('refreshToken', refreshToken);
    Cookies.set('accessToken', accessToken, { httpOnly: false });
    Cookies.set('refreshToken', refreshToken, { httpOnly: false });
  },
  clearAuth: (): void => {
    localStorage.removeItem('user');
    localStorage.removeItem('accessToken');
    localStorage.removeItem('refreshToken');

    // Clear cookies with proper path and domain
    Cookies.remove('accessToken', { path: '/', domain: window.location.hostname });
    Cookies.remove('refreshToken', { path: '/', domain: window.location.hostname });

    // Clear any other potential auth-related cookies
    document.cookie.split(";").forEach((c) => {
      const eqPos = c.indexOf("=");
      const name = eqPos > -1 ? c.substr(0, eqPos).trim() : c.trim();
      if (name.includes('token') || name.includes('auth') || name.includes('session')) {
        Cookies.remove(name, { path: '/', domain: window.location.hostname });
      }
    });
  }
};

const initialState: AuthState = {
  user: storageOps.getUser(),
  isAuthenticated: !!localStorage.getItem('accessToken'),
  loading: false,
  error: null,
};

// Type-safe async thunk helper
type AuthThunkResponse = LoginResponse | { message: string };

const createAuthThunk = <T extends AuthThunkResponse, P = any>(
  name: string, 
  apiCall: (params: P) => Promise<{ success: boolean; data?: T; message?: string }>
) =>
  createAsyncThunk<T, P>(name, async (params: P, { rejectWithValue }) => {
    try {
      const response = await apiCall(params);
      if (!response.success) return rejectWithValue(response.message || 'Operation failed');
      return response.data;
    } catch (error: unknown) {
      const message = error instanceof Error ? error.message : 'Network error occurred';
      return rejectWithValue(message);
    }
  });

export const loginUser = createAuthThunk<LoginResponse>(
  'auth/login',
  (params: { email_address: string; password: string }) => authApi.login(params)
);

export const registerUser = createAuthThunk<{ message: string }>(
  'auth/register',
  (params: { email_address: string; password: string; phone_number: string; user_name: string }) => authApi.register(params)
);

export const sendOtp = createAuthThunk<{ message: string }>(
  'auth/sendOtp',
  (params: string) => authApi.sendOtp(params)
);

export const verifyOtp = createAuthThunk<LoginResponse>(
  'auth/verifyOtp',
  (params: { otp: string; phone_number: string }) => authApi.verifyOtp(params)
);

// Type-safe helper functions
const handleLoading = (state: AuthState, loading: boolean, error: string | null = null) => {
  state.loading = loading;
  if (error !== null) state.error = error;
};

const handleAuthSuccess = (state: AuthState, user: User, accessToken: string, refreshToken: string) => {
  state.user = user;
  state.isAuthenticated = true;
  state.error = null;
  storageOps.setUser(user);
  storageOps.setTokens(accessToken, refreshToken);
};

const authSlice = createSlice({
  name: 'auth',
  initialState,
  reducers: {
    logout: (state) => {
      state.user = null;
      state.isAuthenticated = false;
      state.error = null;
      storageOps.clearAuth();
    },
    clearError: (state) => {
      state.error = null;
    },
    setUser: (state, action: PayloadAction<User>) => {
      state.user = action.payload;
      state.isAuthenticated = true;
      storageOps.setUser(action.payload);
    },
  },
  extraReducers: (builder) => {
    builder
      // Login User
      .addCase(loginUser.pending, (state) => handleLoading(state, true))
      .addCase(loginUser.fulfilled, (state, action: PayloadAction<LoginResponse>) => {
        handleLoading(state, false);
        handleAuthSuccess(state, action.payload.user, action.payload.accessToken, action.payload.refreshToken);
      })
      .addCase(loginUser.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Register User
      .addCase(registerUser.pending, (state) => handleLoading(state, true))
      .addCase(registerUser.fulfilled, (state) => handleLoading(state, false))
      .addCase(registerUser.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Send OTP
      .addCase(sendOtp.pending, (state) => handleLoading(state, true))
      .addCase(sendOtp.fulfilled, (state) => handleLoading(state, false))
      .addCase(sendOtp.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))

      // Verify OTP
      .addCase(verifyOtp.pending, (state) => handleLoading(state, true))
      .addCase(verifyOtp.fulfilled, (state, action: PayloadAction<LoginResponse>) => {
        handleLoading(state, false);
        handleAuthSuccess(state, action.payload.user, action.payload.accessToken, action.payload.refreshToken);
      })
      .addCase(verifyOtp.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string));
  },
});

export const { logout, clearError, setUser } = authSlice.actions;
export default authSlice.reducer;

import { createSlice, createAsyncThunk } from '@reduxjs/toolkit';
import { cartApi } from '../../services/cartApi';
import { Bag, CartItem } from '../../types/api';
import { RootState } from '../store';

interface CartState {
  items: CartItem[];
  guestItems: CartItem[];
  bags: Bag[];
  loading: boolean;
  error: string | null;
  totalItems: number;
  totalAmount: number;
}

const initialState: CartState = {
  items: [],
  guestItems: JSON.parse(localStorage.getItem('guestCart') || '[]'),
  bags: [],
  loading: false,
  error: null,
  totalItems: 0,
  totalAmount: 0,
};

// Consolidated localStorage operations
const localStorageOps = {
  get: (): CartItem[] => {
    try {
      const cart = localStorage.getItem('guestCart');
      return cart ? JSON.parse(cart) : [];
    } catch {
      return [];
    }
  },
  set: (items: CartItem[]): void => {
    try {
      localStorage.setItem('guestCart', JSON.stringify(items));
    } catch (error) {
      console.error('Failed to save cart to localStorage:', error);
    }
  },
  remove: (): void => {
    try {
      localStorage.removeItem('guestCart');
    } catch (error) {
      console.error('Failed to remove cart from localStorage:', error);
    }
  }
};

// Helper function to calculate cart totals
const calculateCartTotals = (state: CartState) => {
  let totalItems = 0;
  let totalAmount = 0;

  if (state.bags.length > 0) {
    state.bags.forEach(bag => {
      if (bag.bag_details?.length) {
        bag.bag_details.forEach(detail => {
          totalItems += detail.product_count || 0;
          totalAmount += (detail.selling_price || 0) * (detail.product_count || 0);
        });
      }
    });
  } else {
    state.guestItems.forEach(item => {
      totalItems += item.product_count || 0;
      totalAmount += parseFloat(item.price || '0') * (item.product_count || 0);
    });
  }

  state.totalItems = totalItems;
  state.totalAmount = totalAmount;
};

// Async thunks with consolidated error handling
const handleAsyncError = (error: any): string => error.message || 'Network error occurred';

export const fetchBag = createAsyncThunk(
  'cart/fetchBag',
  async (store_uid: string, { rejectWithValue, getState }) => {
    const state = getState() as RootState;
    const isAuthenticated = state.auth.isAuthenticated;
    
    try {
      if (!isAuthenticated) {
        return { isGuest: true, data: localStorageOps.get() };
      }
      
      const response = await cartApi.getBag(store_uid);
      if (!response.success) {
        return rejectWithValue(response.message || 'Failed to fetch cart');
      }
      return { isGuest: false, data: response.data || [] };
    } catch (error: any) {
      return rejectWithValue(handleAsyncError(error));
    }
  }
);

export const addToCart = createAsyncThunk(
  'cart/addToCart',
  async (data: any, { rejectWithValue, getState }) => {
    const state = getState() as RootState;
    const { isAuthenticated } = state.auth;
    const { defaultStore } = state.store;

    if (!isAuthenticated) {
      return { ...data, isGuest: true };
    }

    if (!defaultStore?.store_uid) {
      return rejectWithValue('Store not available');
    }

    try {
      const response = await cartApi.addToCart({
        product: {
          product_uid: data.product_uid,
          product_count: data.product_count,
          track_inventory: data.track_inventory,
          product_status: data.product_status,
          product_variant_id: data?.product_variant_id || undefined,
          product_id: parseInt(data.price),
          price: data.price,
          mrp: data.mrp,
          min_order_quantity: data.min_order_quantity,
        },
        slugData: 'CART',
        store_uid: defaultStore.store_uid,
      });

      if (!response.success) {
        return rejectWithValue(response.message || 'Failed to add to cart');
      }
      return { ...data, isGuest: false };
    } catch (error: any) {
      return rejectWithValue(handleAsyncError(error));
    }
  }
);

// Generic cart operation thunk factory
const createCartOperationThunk = (name: string, apiCall: (data: any) => Promise<any>, errorMessage: string) =>
  createAsyncThunk(
    `cart/${name}`,
    async (data: any, { rejectWithValue, getState }) => {
      const state = getState() as RootState;
      const { isAuthenticated } = state.auth;

      if (!isAuthenticated) {
        return { product_uid: data.product_uid, isGuest: true };
      }

      try {
        const response = await apiCall(data);
        if (!response.success) {
          return rejectWithValue(response.message || errorMessage);
        }
        return { product_uid: data.product_uid, isGuest: false };
      } catch (error: any) {
        return rejectWithValue(handleAsyncError(error));
      }
    }
  );

export const incrementQuantity = createCartOperationThunk(
  'incrementQuantity',
  cartApi.incrementQuantity,
  'Failed to increment quantity'
);

export const decrementQuantity = createCartOperationThunk(
  'decrementQuantity',
  cartApi.decrementQuantity,
  'Failed to decrement quantity'
);

export const removeFromCart = createCartOperationThunk(
  'removeFromCart',
  cartApi.removeFromCart,
  'Failed to remove from cart'
);

export const syncGuestCart = createAsyncThunk(
  'cart/syncGuestCart',
  async (data: { guestItems: CartItem[]; store_uid: string }, { rejectWithValue }) => {
    if (data.guestItems.length === 0) return [];

    try {
      const bulkRequest = {
        product: data.guestItems.map(item => ({
          product_uid: item.product_uid,
          product_count: item.product_count,
          track_inventory: item.track_inventory,
          product_status: item.product_status,
          product_id: parseInt(item.price),
          slug: 'CART',
          mrp: item.mrp,
          price: item.price,
          min_order_quantity: item.min_order_quantity,
        })),
        store_uid: data.store_uid,
      };

      const response = await cartApi.createBulkBagProduct(bulkRequest);
      if (!response.success) {
        return rejectWithValue(response.message || 'Failed to sync cart');
      }
      return data.guestItems;
    } catch (error: any) {
      return rejectWithValue(handleAsyncError(error));
    }
  }
);

// Helper function for loading states
const handleLoading = (state: any, loading: boolean, error: string | null = null) => {
  state.loading = loading;
  if (error !== null) state.error = error;
};

// Helper function for guest cart operations
const updateGuestCart = (state: any, items: CartItem[]) => {
  state.guestItems = items;
  localStorageOps.set(items);
  calculateCartTotals(state);
};

const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {},
  extraReducers: (builder) => {
    builder
      // Fetch Bag
      .addCase(fetchBag.pending, (state) => handleLoading(state, true))
      .addCase(fetchBag.fulfilled, (state, action) => {
        handleLoading(state, false);
        const { isGuest, data } = action.payload;
        
        if (isGuest) {
          state.guestItems = Array.isArray(data) ? data as CartItem[] : [];
          state.bags = [];
        } else {
          state.bags = Array.isArray(data) ? data as Bag[] : [];
          state.guestItems = [];
        }
        
        calculateCartTotals(state);
      })
      .addCase(fetchBag.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))
      
      // Add to Cart
      .addCase(addToCart.pending, (state) => handleLoading(state, true))
      .addCase(addToCart.fulfilled, (state, action) => {
        handleLoading(state, false);
        if (action.payload.isGuest) {
          const existingItem = state.guestItems.find(
            item => item.product_uid === action.payload.product_uid
          );
          
          if (existingItem) {
            existingItem.product_count += action.payload.product_count;
          } else {
            state.guestItems.push({
              product_uid: action.payload.product_uid,
              product_count: action.payload.product_count,
              price: action.payload.price,
              mrp: action.payload.mrp,
              product_name: action.payload.product_name,
              product_image: action.payload.product_image,
              track_inventory: action.payload.track_inventory,
              product_status: action.payload.product_status,
              category_uid: action.payload.category_uid,
              min_order_quantity: action.payload.min_order_quantity,
              stock: action.payload.stock
            });
          }
          updateGuestCart(state, state.guestItems);
        }
        calculateCartTotals(state);
      })
      .addCase(addToCart.rejected, (state, action) => 
        handleLoading(state, false, action.payload as string))
      
      // Quantity operations
      .addCase(incrementQuantity.pending, (state) => { state.error = null; })
      .addCase(incrementQuantity.fulfilled, (state, action) => {
        if (action.payload.isGuest) {
          const item = state.guestItems.find(item => item.product_uid === action.payload.product_uid);
          if (item) {
            item.product_count += 1;
            updateGuestCart(state, state.guestItems);
          }
        }
        state.error = null;
      })
      .addCase(incrementQuantity.rejected, (state, action) => { state.error = action.payload as string; })
      
      .addCase(decrementQuantity.pending, (state) => { state.error = null; })
      .addCase(decrementQuantity.fulfilled, (state, action) => {
        if (action.payload.isGuest) {
          const item = state.guestItems.find(item => item.product_uid === action.payload.product_uid);
          if (item) {
            if (item.product_count <= 1) {
              const filteredItems = state.guestItems.filter(i => i.product_uid !== action.payload.product_uid);
              updateGuestCart(state, filteredItems);
            } else {
              item.product_count -= 1;
              updateGuestCart(state, state.guestItems);
            }
          }
        }
        state.error = null;
      })
      .addCase(decrementQuantity.rejected, (state, action) => { state.error = action.payload as string; })
      
      .addCase(removeFromCart.pending, (state) => { state.error = null; })
      .addCase(removeFromCart.fulfilled, (state, action) => {
        if (action.payload.isGuest) {
          const filteredItems = state.guestItems.filter(
            item => item.product_uid !== action.payload.product_uid
          );
          updateGuestCart(state, filteredItems);
        }
        state.error = null;
      })
      .addCase(removeFromCart.rejected, (state, action) => { state.error = action.payload as string; })
      
      // Sync Guest Cart
      .addCase(syncGuestCart.fulfilled, (state) => {
        handleLoading(state, false);
        state.guestItems = [];
        localStorageOps.remove();
        calculateCartTotals(state);
      });
  },
});

export default cartSlice.reducer;

