import { ApiResponse } from '../types/api';

const isValidResponse = (response: unknown): response is Record<string, unknown> => 
  response !== null && typeof response === 'object';

const hasSuccessProperty = (response: Record<string, unknown>): response is ApiResponse<unknown> => 
  'success' in response;

const hasDataProperty = (response: Record<string, unknown>): response is { data: unknown } => 
  'data' in response;

export const handleApiResponse = <T>(
  response: unknown,
  fallbackData?: T
): ApiResponse<T> => {
  if (!isValidResponse(response)) {
    return {
      success: false,
      message: 'Invalid response format'
    };
  }
  if (hasSuccessProperty(response)) {
    return response as ApiResponse<T>;
  }
  if (hasDataProperty(response)) {
    return {
      success: true,
      data: response.data as T
    };
  }
  if (fallbackData !== undefined) {
    return {
      success: true,
      data: response as T
    };
  }
  return {
    success: true,
    data: response as T
  };
};

export const handleApiError = <T>(
  error: Error | unknown, 
  defaultMessage: string
): ApiResponse<T> => {
  const message = error instanceof Error ? error.message : defaultMessage;
  return {
    success: false,
    message
  };
};

export const withErrorHandling = async <T>(
  apiCall: () => Promise<T>,
  errorMessage: string
): Promise<ApiResponse<T>> => {
  try {
    const response = await apiCall();
    return handleApiResponse<T>(response);
  } catch (error) {
    return handleApiError<T>(error, errorMessage);
  }
};

const isMeaningfulValue = (value: any): boolean => 
  value !== '' && value !== null && value !== undefined && 
  !(Array.isArray(value) && value.length === 0);

export const cleanApiParams = <T extends Record<string, any>>(obj: T): Partial<T> => 
  Object.fromEntries(
    Object.entries(obj).filter(([_, value]) => isMeaningfulValue(value))
  ) as Partial<T>;

export const stringifyParams = <T extends Record<string, any>>(obj: T): Record<string, string> => 
  Object.fromEntries(
    Object.entries(obj).map(([key, value]) => [key, String(value)])
  );

export const buildApiParams = <T extends Record<string, any>>(
  params: T,
  defaults: Partial<T> = {}
): Record<string, string> => 
  stringifyParams(cleanApiParams({ ...defaults, ...params }));

import { useMemo } from 'react';
import { Bag, CartItem, BagDetail } from '../types/api';

export const useDerivedCartItems = (
  isGuest: boolean,
  guestItems: CartItem[],
  bags: Bag[]
): (BagDetail | CartItem)[] => {
  return useMemo(() => 
    isGuest ? guestItems : bags.flatMap(bag => bag.bag_details || []),
    [isGuest, guestItems, bags]
  );
};

import { BagDetail, CartItem } from '../types/api';

export const isBagDetail = (item: BagDetail | CartItem): item is BagDetail => 'bag_detail_id' in item;

export const getItemInfo = (item: BagDetail | CartItem) => {
  const isBag = isBagDetail(item);
  const product = isBag ? item.zm_products?.[0] : null;
  const price = isBag ? item.selling_price : parseFloat(item.price);
  const mrp = isBag ? item.mrp_price : parseFloat(item.mrp);
  return {
    productUid: item.product_uid,
    productCount: item.product_count,
    bagDetailId: isBag ? item.bag_detail_id : undefined,
    price, mrp, product,
    name: isBag ? product?.product_name || 'Product' : item.product_name,
    image: isBag ? product?.product_image?.[0]?.product_image : item.product_image,
    stock: isBag ? parseInt(product?.stock || '0') : item.stock || 0,
    trackInventory: isBag ? product?.track_inventory : item.track_inventory,
    minOrderQuantity: isBag ? product?.min_order_quantity || 1 : item.min_order_quantity || 1,
    units: isBag ? item.units || 'unit' : 'unit',
  };
};

export const calculateItemPricing = (item: BagDetail | CartItem) => {
  const { price, mrp, productCount } = getItemInfo(item);
  const discountPercent = mrp > price ? Math.round(((mrp - price) / mrp) * 100) : 0;
  return { price, mrp, discountPercent, totalPrice: price * productCount,
    totalMrp: mrp * productCount, savings: (mrp - price) * productCount };
};

export const checkStockAvailability = (item: BagDetail | CartItem, lowStockThreshold = 10) => {
  const { stock, trackInventory, minOrderQuantity, productCount } = getItemInfo(item);
  return { stock, minOrderQuantity, isLowStock: trackInventory && stock > 0 && stock <= lowStockThreshold,
    isOutOfStock: trackInventory && stock <= 0, canIncrement: !trackInventory || stock > productCount,
    canDecrement: productCount > minOrderQuantity };
};

export const getProductDisplayDetails = (item: BagDetail | CartItem) => {
  const { productCount, price, mrp, name, image, units } = getItemInfo(item);
  const discount = mrp - price;
  return { name, image, price, mrp, units, quantity: productCount, discount,
    discountPercent: mrp > 0 ? Math.round((discount / mrp) * 100) : 0, itemTotal: price * productCount };
};

export const getCartItemInfo = (item: BagDetail | CartItem) => {
  const info = getItemInfo(item);
  return { productUid: info.productUid, productCount: info.productCount, bagDetailId: info.bagDetailId,
    price: info.price, mrp: info.mrp, product: info.product };
};

export const getProductDetails = (item: BagDetail | CartItem) => {
  const info = getItemInfo(item);
  return { name: info.name, image: info.image, stock: info.stock, trackInventory: info.trackInventory,
    minOrderQuantity: info.minOrderQuantity };
};

// String case transformations with minimal overhead
export const lowerCaseFirstLetter = (str: string): string => 
    str ? str[0].toLowerCase() + str.slice(1) : str;

export const upperCaseFirstLetter = (str: string): string => 
    str ? str[0].toUpperCase() + str.slice(1) : str;

  export const toTitleCase = (str: string): string => 
    str ? str.toLowerCase().split(' ').map(w => w[0].toUpperCase() + w.slice(1)).join(' ') : str;

  export const truncate = (str: string, max: number): string => 
    str?.length > max ? str.slice(0, max) + '...' : str;

  export const isEmptyOrWhitespace = (str: string | null | undefined): boolean => 
    !str?.trim();

  export const removeWhitespace = (str: string): string => str.replace(/\s+/g, '');

  export const toKebabCase = (str: string): string => 
    str ? str.trim().toLowerCase().replace(/\s+/g, '-').replace(/[^a-z0-9-]/g, '') : str;

export const toCamelCase = (str: string): string => 
  str ? str.trim().toLowerCase().replace(/[^a-zA-Z0-9]+(.)/g, (_, c) => c.toUpperCase()) : str;

export const lowerCaseAllLetters = (str: string): string => 
  str ? str.toLowerCase() : str;

// Base64 decode and JSON parse utility
export const decodeBase64Json = <T = any>(encodedString: string): T | null => {
  try {
    const decodedString = atob(encodedString);
    const parsedData: T = JSON.parse(decodedString);
    return parsedData;
  } catch (error) {
    console.error('❌ Failed to decode base64 JSON:', error);
    return null;
  }
};

